import { useState, useEffect } from 'react'
import { Folder, FileText, Link, Search, Plus, Trash2, ExternalLink, Tag } from 'lucide-react'

interface Resource {
  id: string
  name: string
  type: 'file' | 'link' | 'document'
  url: string
  description: string
  category: string
  tags: string[]
  createdAt: string
}

const defaultResources: Resource[] = [
  { id: '1', name: 'T109计算平台', type: 'link', url: 'https://t109.mettlyz.com', description: '过渡态计算平台', category: '计算化学', tags: ['T109', '计算'], createdAt: '2024-01-01' },
  { id: '2', name: 'Sobereva博客', type: 'link', url: 'http://sobereva.com', description: '量子化学博客', category: '计算化学', tags: ['量子化学', '学习'], createdAt: '2024-01-01' },
  { id: '3', name: 'PubChem', type: 'link', url: 'https://pubchem.ncbi.nlm.nih.gov', description: '化学分子数据库', category: '数据库', tags: ['化学', '数据库'], createdAt: '2024-01-01' },
  { id: '4', name: 'Google Scholar', type: 'link', url: 'https://scholar.google.com', description: '学术搜索', category: '搜索工具', tags: ['学术', '搜索'], createdAt: '2024-01-01' },
  { id: '5', name: 'arXiv', type: 'link', url: 'https://arxiv.org', description: '预印本论文', category: '学术', tags: ['论文', '预印本'], createdAt: '2024-01-01' },
]

export function Resources() {
  const [resources, setResources] = useState<Resource[]>(defaultResources)
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState('全部')
  const [showAddModal, setShowAddModal] = useState(false)
  const [newResource, setNewResource] = useState<Partial<Resource>>({
    name: '',
    type: 'link',
    url: '',
    description: '',
    category: '',
    tags: []
  })

  const categories = ['全部', ...Array.from(new Set(resources.map(r => r.category)))]

  const filteredResources = resources.filter(r => {
    const matchesSearch = !searchQuery || 
      r.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      r.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      r.tags.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()))
    const matchesCategory = selectedCategory === '全部' || r.category === selectedCategory
    return matchesSearch && matchesCategory
  })

  const handleAddResource = () => {
    if (!newResource.name || !newResource.url) return
    
    const resource: Resource = {
      id: Date.now().toString(),
      name: newResource.name,
      type: newResource.type as 'file' | 'link' | 'document',
      url: newResource.url,
      description: newResource.description || '',
      category: newResource.category || '未分类',
      tags: newResource.tags || [],
      createdAt: new Date().toISOString()
    }
    
    setResources([...resources, resource])
    setShowAddModal(false)
    setNewResource({ name: '', type: 'link', url: '', description: '', category: '', tags: [] })
  }

  const handleDelete = (id: string) => {
    if (confirm('确定要删除这个资源吗？')) {
      setResources(resources.filter(r => r.id !== id))
    }
  }

  const getIcon = (type: string) => {
    switch (type) {
      case 'file': return <FileText size={20} />
      case 'folder': return <Folder size={20} />
      default: return <Link size={20} />
    }
  }

  return (
    <div>
      <div className="page-header">
        <h2 className="page-title">📚 资源库</h2>
        <button
          onClick={() => setShowAddModal(true)}
          style={{
            padding: '10px 20px',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            gap: '8px'
          }}
        >
          <Plus size={18} />
          添加资源
        </button>
      </div>

      {/* 搜索和筛选 */}
      <div style={{
        display: 'flex',
        gap: '16px',
        marginBottom: '24px',
        flexWrap: 'wrap'
      }}>
        <div style={{ position: 'relative', flex: 1, minWidth: '250px' }}>
          <Search size={18} style={{
            position: 'absolute',
            left: '12px',
            top: '50%',
            transform: 'translateY(-50%)',
            color: '#999'
          }} />
          <input
            type="text"
            placeholder="搜索资源..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={{
              width: '100%',
              padding: '10px 12px 10px 40px',
              border: '1px solid #ddd',
              borderRadius: '8px',
              fontSize: '0.95rem'
            }}
          />
        </div>
        
        <select
          value={selectedCategory}
          onChange={(e) => setSelectedCategory(e.target.value)}
          style={{
            padding: '10px 16px',
            border: '1px solid #ddd',
            borderRadius: '8px',
            fontSize: '0.95rem',
            minWidth: '150px'
          }}
        >
          {categories.map(cat => (
            <option key={cat} value={cat}>{cat}</option>
          ))}
        </select>
      </div>

      {/* 资源列表 */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
        gap: '20px'
      }}>
        {filteredResources.map(resource => (
          <div
            key={resource.id}
            style={{
              background: 'white',
              borderRadius: '12px',
              padding: '20px',
              boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
              display: 'flex',
              flexDirection: 'column',
              gap: '12px'
            }}
          >
            <div style={{
              display: 'flex',
              alignItems: 'center',
              gap: '12px'
            }}>
              <div style={{
                width: '40px',
                height: '40px',
                borderRadius: '8px',
                background: '#f0f4ff',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#667eea'
              }}>
                {getIcon(resource.type)}
              </div>
              <div style={{ flex: 1 }}>
                <h4 style={{ margin: 0, fontSize: '1rem' }}>{resource.name}</h4>
                <span style={{
                  fontSize: '0.8rem',
                  color: '#666',
                  padding: '2px 8px',
                  background: '#f0f0f0',
                  borderRadius: '4px'
                }}>
                  {resource.category}
                </span>
              </div>
              <button
                onClick={() => handleDelete(resource.id)}
                style={{
                  padding: '6px',
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  color: '#ef5350'
                }}
              >
                <Trash2 size={16} />
              </button>
            </div>

            <p style={{
              margin: 0,
              color: '#666',
              fontSize: '0.9rem',
              lineHeight: 1.5
            }}>
              {resource.description}
            </p>

            {resource.tags.length > 0 && (
              <div style={{
                display: 'flex',
                gap: '6px',
                flexWrap: 'wrap'
              }}>
                {resource.tags.map((tag, i) => (
                  <span
                    key={i}
                    style={{
                      fontSize: '0.75rem',
                      color: '#667eea',
                      background: '#f0f4ff',
                      padding: '2px 8px',
                      borderRadius: '4px',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '4px'
                    }}
                  >
                    <Tag size={10} />
                    {tag}
                  </span>
                ))}
              </div>
            )}

            <a
              href={resource.url}
              target="_blank"
              rel="noopener noreferrer"
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '6px',
                color: '#667eea',
                textDecoration: 'none',
                fontSize: '0.9rem',
                marginTop: 'auto'
              }}
            >
              <ExternalLink size={14} />
              访问资源
            </a>
          </div>
        ))}
      </div>

      {filteredResources.length === 0 && (
        <div style={{
          textAlign: 'center',
          padding: '60px 20px',
          color: '#999'
        }}>
          <Folder size={48} style={{ marginBottom: '16px', opacity: 0.5 }} />
          <p>没有找到匹配的资源</p>
        </div>
      )}

      {/* 添加资源弹窗 */}
      {showAddModal && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000
          }}
          onClick={() => setShowAddModal(false)}
        >
          <div
            style={{
              background: 'white',
              borderRadius: '12px',
              padding: '24px',
              width: '90%',
              maxWidth: '500px',
              maxHeight: '80vh',
              overflow: 'auto'
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 style={{ marginBottom: '20px' }}>添加资源</h3>
            
            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  资源名称 *
                </label>
                <input
                  type="text"
                  value={newResource.name}
                  onChange={(e) => setNewResource({ ...newResource, name: e.target.value })}
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px'
                  }}
                />
              </div>
              
              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  资源链接 *
                </label>
                <input
                  type="url"
                  value={newResource.url}
                  onChange={(e) => setNewResource({ ...newResource, url: e.target.value })}
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px'
                  }}
                />
              </div>
              
              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  分类
                </label>
                <input
                  type="text"
                  value={newResource.category}
                  onChange={(e) => setNewResource({ ...newResource, category: e.target.value })}
                  placeholder="例如：计算化学、学术资源"
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px'
                  }}
                />
              </div>
              
              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  描述
                </label>
                <textarea
                  value={newResource.description}
                  onChange={(e) => setNewResource({ ...newResource, description: e.target.value })}
                  rows={3}
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px',
                    resize: 'vertical'
                  }}
                />
              </div>
            </div>
            
            <div style={{
              display: 'flex',
              gap: '12px',
              justifyContent: 'flex-end',
              marginTop: '24px'
            }}>
              <button
                onClick={() => setShowAddModal(false)}
                style={{
                  padding: '10px 20px',
                  background: '#f0f0f0',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer'
                }}
              >
                取消
              </button>
              <button
                onClick={handleAddResource}
                disabled={!newResource.name || !newResource.url}
                style={{
                  padding: '10px 20px',
                  background: (!newResource.name || !newResource.url) ? '#ccc' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: (!newResource.name || !newResource.url) ? 'not-allowed' : 'pointer'
                }}
              >
                添加
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
