import { useState, useEffect } from 'react'
import './UserManagement.css'

interface User {
  id: number
  username: string
  email: string
  role: string
  status: string
  created_at: string
  last_login: string | null
}

interface UserStats {
  total: number
  active: number
  disabled: number
  new_today: number
  role_distribution: Record<string, number>
}

export function UserManagement() {
  const [users, setUsers] = useState<User[]>([])
  const [stats, setStats] = useState<UserStats | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [filter, setFilter] = useState({ status: '', role: '', search: '' })
  const [selectedUser, setSelectedUser] = useState<User | null>(null)
  const [showModal, setShowModal] = useState(false)

  const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8086'
  const token = localStorage.getItem('kanban_token')

  useEffect(() => {
    fetchUsers()
    fetchStats()
  }, [page, filter])

  const fetchUsers = async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams({
        page: page.toString(),
        per_page: '20',
        ...(filter.status && { status: filter.status }),
        ...(filter.role && { role: filter.role }),
        ...(filter.search && { search: filter.search })
      })

      const response = await fetch(`${API_URL}/api/admin/users?${params}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()

      if (data.success) {
        setUsers(data.data.users)
        setTotalPages(data.data.total_pages)
      } else {
        setError(data.error || '获取用户列表失败')
      }
    } catch (err) {
      setError('网络错误')
    } finally {
      setLoading(false)
    }
  }

  const fetchStats = async () => {
    try {
      const response = await fetch(`${API_URL}/api/admin/users/stats`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()

      if (data.success) {
        setStats(data.data)
      }
    } catch (err) {
      console.error('获取统计失败:', err)
    }
  }

  const handleStatusChange = async (userId: number, newStatus: string) => {
    if (!confirm(`确定要${newStatus === 'active' ? '启用' : '禁用'}该用户吗？`)) {
      return
    }

    try {
      const response = await fetch(`${API_URL}/api/admin/users/${userId}/status`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ status: newStatus })
      })
      const data = await response.json()

      if (data.success) {
        fetchUsers()
        fetchStats()
      } else {
        alert(data.error || '操作失败')
      }
    } catch (err) {
      alert('网络错误')
    }
  }

  const handleRoleChange = async (userId: number, newRole: string) => {
    if (!confirm(`确定要将该用户角色改为 ${newRole} 吗？`)) {
      return
    }

    try {
      const response = await fetch(`${API_URL}/api/admin/users/${userId}/role`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ role: newRole })
      })
      const data = await response.json()

      if (data.success) {
        fetchUsers()
        fetchStats()
      } else {
        alert(data.error || '操作失败')
      }
    } catch (err) {
      alert('网络错误')
    }
  }

  const handleDelete = async (userId: number) => {
    if (!confirm('确定要删除该用户吗？此操作不可恢复！')) {
      return
    }

    try {
      const response = await fetch(`${API_URL}/api/admin/users/${userId}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()

      if (data.success) {
        fetchUsers()
        fetchStats()
      } else {
        alert(data.error || '删除失败')
      }
    } catch (err) {
      alert('网络错误')
    }
  }

  const viewUserDetail = async (userId: number) => {
    try {
      const response = await fetch(`${API_URL}/api/admin/users/${userId}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()

      if (data.success) {
        setSelectedUser(data.data)
        setShowModal(true)
      }
    } catch (err) {
      alert('获取用户详情失败')
    }
  }

  const getRoleBadgeColor = (role: string) => {
    switch (role) {
      case 'super_admin': return '#ef4444'
      case 'admin': return '#f59e0b'
      default: return '#6b7280'
    }
  }

  const getRoleText = (role: string) => {
    switch (role) {
      case 'super_admin': return '超级管理员'
      case 'admin': return '管理员'
      default: return '普通用户'
    }
  }

  const getStatusBadge = (status: string) => {
    const isActive = status === 'active'
    return (
      <span 
        className="status-badge"
        style={{ 
          backgroundColor: isActive ? '#d1fae5' : '#fee2e2',
          color: isActive ? '#065f46' : '#991b1b'
        }}
      >
        {isActive ? '正常' : '已禁用'}
      </span>
    )
  }

  return (
    <div className="user-management">
      <h1>用户管理</h1>

      {/* 统计卡片 */}
      {stats && (
        <div className="stats-row">
          <div className="stat-box">
            <span className="stat-number">{stats.total}</span>
            <span className="stat-label">总用户</span>
          </div>
          <div className="stat-box active">
            <span className="stat-number">{stats.active}</span>
            <span className="stat-label">活跃用户</span>
          </div>
          <div className="stat-box disabled">
            <span className="stat-number">{stats.disabled}</span>
            <span className="stat-label">已禁用</span>
          </div>
          <div className="stat-box new">
            <span className="stat-number">{stats.new_today}</span>
            <span className="stat-label">今日新增</span>
          </div>
        </div>
      )}

      {/* 筛选器 */}
      <div className="filter-bar">
        <input
          type="text"
          placeholder="搜索用户名或邮箱..."
          value={filter.search}
          onChange={(e) => setFilter({ ...filter, search: e.target.value })}
          className="search-input"
        />
        <select
          value={filter.status}
          onChange={(e) => setFilter({ ...filter, status: e.target.value })}
          className="filter-select"
        >
          <option value="">所有状态</option>
          <option value="active">正常</option>
          <option value="disabled">已禁用</option>
        </select>
        <select
          value={filter.role}
          onChange={(e) => setFilter({ ...filter, role: e.target.value })}
          className="filter-select"
        >
          <option value="">所有角色</option>
          <option value="user">普通用户</option>
          <option value="admin">管理员</option>
          <option value="super_admin">超级管理员</option>
        </select>
        <button onClick={() => { setPage(1); fetchUsers(); }} className="btn-primary">
          搜索
        </button>
      </div>

      {/* 用户表格 */}
      {loading ? (
        <div className="admin-loading">加载中...</div>
      ) : error ? (
        <div className="admin-error">{error}</div>
      ) : (
        <>
          <table className="admin-table user-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>用户名</th>
                <th>邮箱</th>
                <th>角色</th>
                <th>状态</th>
                <th>创建时间</th>
                <th>最后登录</th>
                <th>操作</th>
              </tr>
            </thead>
            <tbody>
              {users.map(user => (
                <tr key={user.id}>
                  <td>{user.id}</td>
                  <td>{user.username}</td>
                  <td>{user.email || '-'}</td>
                  <td>
                    <span 
                      className="role-badge"
                      style={{ backgroundColor: getRoleBadgeColor(user.role) }}
                    >
                      {getRoleText(user.role)}
                    </span>
                  </td>
                  <td>{getStatusBadge(user.status)}</td>
                  <td>{new Date(user.created_at).toLocaleDateString()}</td>
                  <td>{user.last_login ? new Date(user.last_login).toLocaleString() : '-'}</td>
                  <td>
                    <div className="action-buttons">
                      <button 
                        className="btn-icon" 
                        onClick={() => viewUserDetail(user.id)}
                        title="查看详情"
                      >
                        👁️
                      </button>
                      <button 
                        className={`btn-icon ${user.status === 'active' ? 'danger' : 'success'}`}
                        onClick={() => handleStatusChange(user.id, user.status === 'active' ? 'disabled' : 'active')}
                        title={user.status === 'active' ? '禁用' : '启用'}
                      >
                        {user.status === 'active' ? '🚫' : '✅'}
                      </button>
                      <select
                        className="role-select"
                        value={user.role}
                        onChange={(e) => handleRoleChange(user.id, e.target.value)}
                        title="修改角色"
                      >
                        <option value="user">普通用户</option>
                        <option value="admin">管理员</option>
                        <option value="super_admin">超级管理员</option>
                      </select>
                      <button 
                        className="btn-icon danger"
                        onClick={() => handleDelete(user.id)}
                        title="删除"
                      >
                        🗑️
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* 分页 */}
          <div className="pagination">
            <button 
              disabled={page === 1}
              onClick={() => setPage(page - 1)}
              className="btn-page"
            >
              上一页
            </button>
            <span className="page-info">
              第 {page} 页 / 共 {totalPages} 页
            </span>
            <button 
              disabled={page === totalPages}
              onClick={() => setPage(page + 1)}
              className="btn-page"
            >
              下一页
            </button>
          </div>
        </>
      )}

      {/* 用户详情弹窗 */}
      {showModal && selectedUser && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>用户详情</h2>
              <button className="btn-close" onClick={() => setShowModal(false)}>×</button>
            </div>
            <div className="modal-body">
              <div className="detail-row">
                <span className="detail-label">ID:</span>
                <span className="detail-value">{selectedUser.id}</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">用户名:</span>
                <span className="detail-value">{selectedUser.username}</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">邮箱:</span>
                <span className="detail-value">{selectedUser.email || '-'}</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">角色:</span>
                <span className="detail-value">{getRoleText(selectedUser.role)}</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">状态:</span>
                <span className="detail-value">{getStatusBadge(selectedUser.status)}</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">创建时间:</span>
                <span className="detail-value">{new Date(selectedUser.created_at).toLocaleString()}</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">最后登录:</span>
                <span className="detail-value">
                  {selectedUser.last_login ? new Date(selectedUser.last_login).toLocaleString() : '-'}
                </span>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
