import { useState, useEffect } from 'react'
import './TaskMonitor.css'

interface TaskQueueStatus {
  total_by_status: Record<string, number>
  recent_24h: Record<string, number>
  pending_tasks: Array<{
    id: number
    title: string
    status: string
    priority: number
    created_at: string
  }>
}

interface WorkerStatus {
  worker_id: string
  status: string
  current_task: string | null
  last_heartbeat: string
  cpu_usage: number
  memory_usage: number
  tasks_processed: number
  tasks_failed: number
}

interface ResourceUsage {
  cpu: {
    percent: number
    count: number
    per_cpu: number[]
  }
  memory: {
    total: number
    available: number
    percent: number
    used: number
    free: number
  }
  disk: {
    total: number
    used: number
    free: number
    percent: number
  }
  network: {
    bytes_sent: number
    bytes_recv: number
    packets_sent: number
    packets_recv: number
  }
  timestamp: string
}

export function TaskMonitor() {
  const [queueStatus, setQueueStatus] = useState<TaskQueueStatus | null>(null)
  const [workers, setWorkers] = useState<WorkerStatus[]>([])
  const [resources, setResources] = useState<ResourceUsage | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [activeTab, setActiveTab] = useState<'queue' | 'workers' | 'resources'>('queue')

  const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8086'
  const token = localStorage.getItem('kanban_token')

  useEffect(() => {
    fetchAllData()
    const interval = setInterval(fetchAllData, 5000) // 每5秒刷新
    return () => clearInterval(interval)
  }, [])

  const fetchAllData = async () => {
    await Promise.all([
      fetchQueueStatus(),
      fetchWorkers(),
      fetchResources()
    ])
    setLoading(false)
  }

  const fetchQueueStatus = async () => {
    try {
      const response = await fetch(`${API_URL}/api/admin/tasks/queue`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()
      if (data.success) {
        setQueueStatus(data.data)
      }
    } catch (err) {
      console.error('获取任务队列失败:', err)
    }
  }

  const fetchWorkers = async () => {
    try {
      const response = await fetch(`${API_URL}/api/admin/workers`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()
      if (data.success) {
        setWorkers(data.data)
      }
    } catch (err) {
      console.error('获取Worker状态失败:', err)
    }
  }

  const fetchResources = async () => {
    try {
      const response = await fetch(`${API_URL}/api/admin/resources`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()
      if (data.success) {
        setResources(data.data)
      }
    } catch (err) {
      console.error('获取资源使用失败:', err)
    }
  }

  const formatBytes = (bytes: number) => {
    if (bytes === 0) return '0 B'
    const k = 1024
    const sizes = ['B', 'KB', 'MB', 'GB', 'TB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'idle': return '#10b981'
      case 'busy': return '#f59e0b'
      case 'offline': return '#6b7280'
      case 'error': return '#ef4444'
      default: return '#6b7280'
    }
  }

  const getPriorityLabel = (priority: number) => {
    switch (priority) {
      case 3: return { text: '高', color: '#ef4444' }
      case 2: return { text: '中', color: '#f59e0b' }
      default: return { text: '低', color: '#6b7280' }
    }
  }

  if (loading) return <div className="admin-loading">加载中...</div>
  if (error) return <div className="admin-error">{error}</div>

  return (
    <div className="task-monitor">
      <h1>任务监控</h1>

      {/* 标签页 */}
      <div className="tabs">
        <button 
          className={`tab ${activeTab === 'queue' ? 'active' : ''}`}
          onClick={() => setActiveTab('queue')}
        >
          任务队列
        </button>
        <button 
          className={`tab ${activeTab === 'workers' ? 'active' : ''}`}
          onClick={() => setActiveTab('workers')}
        >
          Worker状态
        </button>
        <button 
          className={`tab ${activeTab === 'resources' ? 'active' : ''}`}
          onClick={() => setActiveTab('resources')}
        >
          资源使用
        </button>
      </div>

      {/* 任务队列 */}
      {activeTab === 'queue' && queueStatus && (
        <div className="tab-content">
          {/* 任务统计卡片 */}
          <div className="queue-stats">
            {Object.entries(queueStatus.total_by_status).map(([status, count]) => (
              <div key={status} className={`queue-stat-card ${status}`}>
                <span className="queue-stat-number">{count}</span>
                <span className="queue-stat-label">{status}</span>
              </div>
            ))}
          </div>

          {/* 待处理任务列表 */}
          <div className="pending-tasks">
            <h2>待处理任务 ({queueStatus.pending_tasks.length})</h2>
            {queueStatus.pending_tasks.length === 0 ? (
              <div className="empty-state">暂无待处理任务</div>
            ) : (
              <table className="admin-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>标题</th>
                    <th>状态</th>
                    <th>优先级</th>
                    <th>创建时间</th>
                  </tr>
                </thead>
                <tbody>
                  {queueStatus.pending_tasks.map(task => {
                    const priority = getPriorityLabel(task.priority)
                    return (
                      <tr key={task.id}>
                        <td>{task.id}</td>
                        <td>{task.title}</td>
                        <td>
                          <span className={`status-tag ${task.status}`}>
                            {task.status}
                          </span>
                        </td>
                        <td>
                          <span 
                            className="priority-badge"
                            style={{ backgroundColor: priority.color }}
                          >
                            {priority.text}
                          </span>
                        </td>
                        <td>{new Date(task.created_at).toLocaleString()}</td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            )}
          </div>
        </div>
      )}

      {/* Worker状态 */}
      {activeTab === 'workers' && (
        <div className="tab-content">
          <div className="workers-grid">
            {workers.map(worker => (
              <div key={worker.worker_id} className="worker-card">
                <div className="worker-header">
                  <h3>{worker.worker_id}</h3>
                  <span 
                    className="worker-status"
                    style={{ backgroundColor: getStatusColor(worker.status) }}
                  >
                    {worker.status}
                  </span>
                </div>
                
                <div className="worker-info">
                  <div className="info-row">
                    <span className="info-label">当前任务:</span>
                    <span className="info-value">{worker.current_task || '无'}</span>
                  </div>
                  <div className="info-row">
                    <span className="info-label">最后心跳:</span>
                    <span className="info-value">
                      {new Date(worker.last_heartbeat).toLocaleTimeString()}
                    </span>
                  </div>
                </div>

                <div className="worker-metrics">
                  <div className="metric">
                    <span className="metric-label">CPU</span>
                    <div className="metric-bar">
                      <div 
                        className="metric-fill"
                        style={{ width: `${worker.cpu_usage}%` }}
                      />
                    </div>
                    <span className="metric-value">{worker.cpu_usage.toFixed(1)}%</span>
                  </div>
                  <div className="metric">
                    <span className="metric-label">内存</span>
                    <div className="metric-bar">
                      <div 
                        className="metric-fill"
                        style={{ width: `${worker.memory_usage}%` }}
                      />
                    </div>
                    <span className="metric-value">{worker.memory_usage.toFixed(1)}%</span>
                  </div>
                </div>

                <div className="worker-stats">
                  <div className="stat">
                    <span className="stat-value success">{worker.tasks_processed}</span>
                    <span className="stat-label">已处理</span>
                  </div>
                  <div className="stat">
                    <span className="stat-value error">{worker.tasks_failed}</span>
                    <span className="stat-label">失败</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 资源使用 */}
      {activeTab === 'resources' && resources && (
        <div className="tab-content">
          <div className="resources-grid">
            {/* CPU */}
            <div className="resource-card">
              <h3>CPU 使用率</h3>
              <div className="resource-main">
                <div className="resource-circle">
                  <span className="resource-percent">{resources.cpu.percent.toFixed(1)}%</span>
                </div>
                <div className="resource-detail">
                  <p>核心数: {resources.cpu.count}</p>
                </div>
              </div>
              <div className="cpu-cores">
                {resources.cpu.per_cpu.map((usage, index) => (
                  <div key={index} className="core-bar">
                    <span className="core-label">{index + 1}</span>
                    <div className="core-fill-container">
                      <div 
                        className="core-fill"
                        style={{ width: `${usage}%` }}
                      />
                    </div>
                    <span className="core-value">{usage.toFixed(0)}%</span>
                  </div>
                ))}
              </div>
            </div>

            {/* 内存 */}
            <div className="resource-card">
              <h3>内存使用</h3>
              <div className="resource-main">
                <div className="resource-circle">
                  <span className="resource-percent">{resources.memory.percent.toFixed(1)}%</span>
                </div>
                <div className="resource-detail">
                  <p>已用: {formatBytes(resources.memory.used)}</p>
                  <p>可用: {formatBytes(resources.memory.available)}</p>
                  <p>总计: {formatBytes(resources.memory.total)}</p>
                </div>
              </div>
              <div className="memory-bar">
                <div 
                  className="memory-fill"
                  style={{ 
                    width: `${resources.memory.percent}%`,
                    backgroundColor: resources.memory.percent > 80 ? '#ef4444' : '#3b82f6'
                  }}
                />
              </div>
            </div>

            {/* 磁盘 */}
            <div className="resource-card">
              <h3>磁盘使用</h3>
              <div className="resource-main">
                <div className="resource-circle">
                  <span className="resource-percent">{resources.disk.percent.toFixed(1)}%</span>
                </div>
                <div className="resource-detail">
                  <p>已用: {formatBytes(resources.disk.used)}</p>
                  <p>可用: {formatBytes(resources.disk.free)}</p>
                  <p>总计: {formatBytes(resources.disk.total)}</p>
                </div>
              </div>
              <div className="disk-bar">
                <div 
                  className="disk-fill"
                  style={{ 
                    width: `${resources.disk.percent}%`,
                    backgroundColor: resources.disk.percent > 80 ? '#ef4444' : '#10b981'
                  }}
                />
              </div>
            </div>

            {/* 网络 */}
            <div className="resource-card wide">
              <h3>网络 I/O</h3>
              <div className="network-stats">
                <div className="network-stat">
                  <span className="network-icon">⬆️</span>
                  <div className="network-info">
                    <span className="network-value">{formatBytes(resources.network.bytes_sent)}</span>
                    <span className="network-label">发送</span>
                  </div>
                </div>
                <div className="network-stat">
                  <span className="network-icon">⬇️</span>
                  <div className="network-info">
                    <span className="network-value">{formatBytes(resources.network.bytes_recv)}</span>
                    <span className="network-label">接收</span>
                  </div>
                </div>
                <div className="network-stat">
                  <span className="network-icon">📦</span>
                  <div className="network-info">
                    <span className="network-value">{resources.network.packets_sent.toLocaleString()}</span>
                    <span className="network-label">发送包</span>
                  </div>
                </div>
                <div className="network-stat">
                  <span className="network-icon">📥</span>
                  <div className="network-info">
                    <span className="network-value">{resources.network.packets_recv.toLocaleString()}</span>
                    <span className="network-label">接收包</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
