import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { 
  Users, Plus, Search, User, Mail, Phone, Building, 
  Loader2, Edit2, Trash2, AlertTriangle, CheckCircle2 
} from 'lucide-react'

interface Person {
  id: number
  name: string
  english_name?: string
  position?: string
  company?: string
  department?: string
  email?: string
  phone?: string
  location?: string
  expertise?: string[]
  avatar_url?: string
  created_at: string
  updated_at: string
}

const API_BASE = '/api'

export function PersonList() {
  const navigate = useNavigate()
  const [persons, setPersons] = useState<Person[]>([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState('')
  const [showAddModal, setShowAddModal] = useState(false)
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null)
  const [newPerson, setNewPerson] = useState({
    name: '',
    english_name: '',
    position: '',
    company: '',
    department: '',
    email: '',
    phone: '',
    location: '',
    bio: '',
    expertise: ''
  })

  useEffect(() => {
    fetchPersons()
  }, [])

  const fetchPersons = async () => {
    setLoading(true)
    try {
      const res = await fetch(`${API_BASE}/persons`)
      const data = await res.json()
      if (data.success) {
        setPersons(data.persons || [])
      } else {
        showToast('加载失败', 'error')
      }
    } catch (error) {
      console.error('Error fetching persons:', error)
      showToast('加载失败', 'error')
    } finally {
      setLoading(false)
    }
  }

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type })
    setTimeout(() => setToast(null), 3000)
  }

  const handleAddPerson = async () => {
    if (!newPerson.name) {
      showToast('请输入姓名', 'error')
      return
    }

    try {
      const res = await fetch(`${API_BASE}/persons`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...newPerson,
          expertise: newPerson.expertise.split(',').map(s => s.trim()).filter(Boolean)
        })
      })
      const data = await res.json()
      if (data.success) {
        showToast('添加成功')
        setShowAddModal(false)
        setNewPerson({
          name: '',
          english_name: '',
          position: '',
          company: '',
          department: '',
          email: '',
          phone: '',
          location: '',
          bio: '',
          expertise: ''
        })
        fetchPersons()
      } else {
        showToast(data.message || '添加失败', 'error')
      }
    } catch (error) {
      showToast('添加失败', 'error')
    }
  }

  const handleDeletePerson = async (id: number, name: string) => {
    if (!confirm(`确定要删除人员 "${name}" 吗？`)) return

    try {
      const res = await fetch(`${API_BASE}/persons/${id}`, {
        method: 'DELETE'
      })
      const data = await res.json()
      if (data.success) {
        showToast('删除成功')
        fetchPersons()
      } else {
        showToast(data.message || '删除失败', 'error')
      }
    } catch (error) {
      showToast('删除失败', 'error')
    }
  }

  const filteredPersons = persons.filter(person =>
    person.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    person.english_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    person.company?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    person.position?.toLowerCase().includes(searchTerm.toLowerCase())
  )

  return (
    <div className="page-container">
      {toast && (
        <div style={{ 
          position: 'fixed', top: '80px', right: '24px', 
          background: toast.type === 'success' ? '#28a745' : '#dc3545',
          color: 'white', padding: '12px 20px', borderRadius: '8px', 
          zIndex: 3000, display: 'flex', alignItems: 'center', gap: '8px' 
        }}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
          {toast.message}
        </div>
      )}

      {/* Header */}
      <div className="page-header">
        <h2 className="page-title">
          <Users size={28} style={{ marginRight: '12px', verticalAlign: 'middle' }} />
          人员管理
        </h2>
        <button 
          onClick={() => setShowAddModal(true)}
          className="primary-btn"
          style={{ display: 'flex', alignItems: 'center', gap: '8px' }}
        >
          <Plus size={20} />
          添加人员
        </button>
      </div>

      {/* Search */}
      <div style={{ marginBottom: '24px' }}>
        <div style={{ position: 'relative', maxWidth: '400px' }}>
          <Search size={20} color="#999" style={{ position: 'absolute', left: '12px', top: '10px' }} />
          <input
            type="text"
            placeholder="搜索姓名、公司、职位..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{
              width: '100%', padding: '10px 10px 10px 40px',
              border: '1px solid #e9ecef', borderRadius: '8px',
              fontSize: '14px'
            }}
          />
        </div>
      </div>

      {/* List */}
      {loading ? (
        <div style={{ display: 'flex', justifyContent: 'center', padding: '100px' }}>
          <Loader2 size={48} color="#667eea" className="animate-spin" />
        </div>
      ) : filteredPersons.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '60px 20px', color: '#999' }}>
          <Users size={64} style={{ opacity: 0.3, marginBottom: '16px' }} />
          <p>{searchTerm ? '没有找到匹配的人员' : '暂无人员数据'}</p>
          <button 
            onClick={() => setShowAddModal(true)}
            style={{ marginTop: '16px', padding: '10px 20px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}
          >
            添加第一个人员
          </button>
        </div>
      ) : (
        <div style={{ display: 'grid', gap: '16px', gridTemplateColumns: 'repeat(auto-fill, minmax(350px, 1fr))' }}>
          {filteredPersons.map(person => (
            <div 
              key={person.id} 
              className="card hover-card"
              style={{ cursor: 'pointer', transition: 'transform 0.2s' }}
              onClick={() => navigate(`/persons/${person.id}`)}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '16px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                  <div style={{ 
                    width: '48px', height: '48px', borderRadius: '50%', 
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', 
                    color: 'white', fontSize: '1.2rem', fontWeight: 'bold'
                  }}>
                    {person.name?.[0] || '?'}
                  </div>
                  <div>
                    <h3 style={{ margin: 0, fontSize: '16px' }}>{person.name}</h3>
                    {person.english_name && <p style={{ margin: '2px 0 0 0', color: '#999', fontSize: '13px' }}>{person.english_name}</p>}
                  </div>
                </div>
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    handleDeletePerson(person.id, person.name)
                  }}
                  style={{
                    padding: '6px', background: 'none', border: 'none',
                    cursor: 'pointer', color: '#dc3545', opacity: 0.6
                  }}
                >
                  <Trash2 size={16} />
                </button>
              </div>

              <div style={{ display: 'grid', gap: '8px' }}>
                {person.position && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: '#666' }}>
                    <Building size={16} color="#667eea" />
                    <span>{person.position}</span>
                  </div>
                )}
                {person.company && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: '#666' }}>
                    <Building size={16} color="#667eea" />
                    <span>{person.company}</span>
                  </div>
                )}
                {person.department && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: '#666' }}>
                    <User size={16} color="#667eea" />
                    <span>{person.department}</span>
                  </div>
                )}
                {person.email && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: '#666' }}>
                    <Mail size={16} color="#667eea" />
                    <span>{person.email}</span>
                  </div>
                )}
                {person.phone && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: '#666' }}>
                    <Phone size={16} color="#667eea" />
                    <span>{person.phone}</span>
                  </div>
                )}
              </div>

              {person.expertise && person.expertise.length > 0 && (
                <div style={{ marginTop: '12px', display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
                  {person.expertise.slice(0, 3).map((exp, idx) => (
                    <span key={idx} style={{
                      padding: '2px 8px', background: '#f0f0f0', borderRadius: '12px', fontSize: '12px', color: '#666'
                    }}>{exp}</span>
                  ))}
                  {person.expertise.length > 3 && (
                    <span style={{ fontSize: '12px', color: '#999' }}>+{person.expertise.length - 3}</span>
                  )}
                </div>
              )}

              <div style={{ marginTop: '16px', paddingTop: '16px', borderTop: '1px solid #e9ecef', textAlign: 'right' }}>
                <span style={{ color: '#667eea', fontSize: '14px' }}>查看详情 →</span>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Add Modal */}
      {showAddModal && (
        <div style={{
          position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 2000
        }}>
          <div style={{
            background: 'white', borderRadius: '12px', padding: '24px',
            width: '90%', maxWidth: '600px', maxHeight: '90vh', overflow: 'auto'
          }}>
            <h3 style={{ margin: '0 0 20px 0' }}>添加人员</h3>
            
            <div style={{ display: 'grid', gap: '16px' }}>
              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>姓名 *</label>
                <input
                  type="text"
                  value={newPerson.name}
                  onChange={(e) => setNewPerson({...newPerson, name: e.target.value})}
                  style={{ width: '100%', padding: '10px', border: '1px solid #e9ecef', borderRadius: '8px' }}
                  placeholder="请输入姓名"
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>英文名</label>
                <input
                  type="text"
                  value={newPerson.english_name}
                  onChange={(e) => setNewPerson({...newPerson, english_name: e.target.value})}
                  style={{ width: '100%', padding: '10px', border: '1px solid #e9ecef', borderRadius: '8px' }}
                  placeholder="请输入英文名"
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>职位</label>
                <input
                  type="text"
                  value={newPerson.position}
                  onChange={(e) => setNewPerson({...newPerson, position: e.target.value})}
                  style={{ width: '100%', padding: '10px', border: '1px solid #e9ecef', borderRadius: '8px' }}
                  placeholder="请输入职位"
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>公司</label>
                <input
                  type="text"
                  value={newPerson.company}
                  onChange={(e) => setNewPerson({...newPerson, company: e.target.value})}
                  style={{ width: '100%', padding: '10px', border: '1px solid #e9ecef', borderRadius: '8px' }}
                  placeholder="请输入公司"
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>部门</label>
                <input
                  type="text"
                  value={newPerson.department}
                  onChange={(e) => setNewPerson({...newPerson, department: e.target.value})}
                  style={{ width: '100%', padding: '10px', border: '1px solid #e9ecef', borderRadius: '8px' }}
                  placeholder="请输入部门"
                />
              </div>

              <div style={{ display: 'grid', gap: '16px', gridTemplateColumns: '1fr 1fr' }}>
                <div>
                  <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>邮箱</label>
                  <input
                    type="email"
                    value={newPerson.email}
                    onChange={(e) => setNewPerson({...newPerson, email: e.target.value})}
                    style={{ width: '100%', padding: '10px', border: '1px solid #e9ecef', borderRadius: '8px' }}
                    placeholder="请输入邮箱"
                  />
                </div>

                <div>
                  <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>电话</label>
                  <input
                    type="tel"
                    value={newPerson.phone}
                    onChange={(e) => setNewPerson({...newPerson, phone: e.target.value})}
                    style={{ width: '100%', padding: '10px', border: '1px solid #e9ecef', borderRadius: '8px' }}
                    placeholder="请输入电话"
                  />
                </div>
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>所在地</label>
                <input
                  type="text"
                  value={newPerson.location}
                  onChange={(e) => setNewPerson({...newPerson, location: e.target.value})}
                  style={{ width: '100%', padding: '10px', border: '1px solid #e9ecef', borderRadius: '8px' }}
                  placeholder="请输入所在地"
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>专业领域（逗号分隔）</label>
                <input
                  type="text"
                  value={newPerson.expertise}
                  onChange={(e) => setNewPerson({...newPerson, expertise: e.target.value})}
                  style={{ width: '100%', padding: '10px', border: '1px solid #e9ecef', borderRadius: '8px' }}
                  placeholder="例如：计算化学，AI，材料科学"
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>个人简介</label>
                <textarea
                  value={newPerson.bio}
                  onChange={(e) => setNewPerson({...newPerson, bio: e.target.value})}
                  style={{ width: '100%', padding: '10px', border: '1px solid #e9ecef', borderRadius: '8px', minHeight: '100px' }}
                  placeholder="请输入个人简介"
                />
              </div>
            </div>

            <div style={{ display: 'flex', gap: '12px', marginTop: '24px', justifyContent: 'flex-end' }}>
              <button
                onClick={() => setShowAddModal(false)}
                style={{ padding: '10px 20px', background: '#f0f0f0', border: 'none', borderRadius: '8px', cursor: 'pointer' }}
              >
                取消
              </button>
              <button
                onClick={handleAddPerson}
                style={{ padding: '10px 20px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}
              >
                添加
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
