import { useState, useEffect } from 'react'
import './SystemConfig.css'

interface ConfigItem {
  id: number
  config_key: string
  config_value: string
  config_type: string
  description: string
  updated_at: string
}

interface EmailTemplate {
  id: number
  template_name: string
  subject: string
  body: string
  variables: string[]
  is_active: boolean
  updated_at: string
}

export function SystemConfig() {
  const [configs, setConfigs] = useState<ConfigItem[]>([])
  const [templates, setTemplates] = useState<EmailTemplate[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [activeTab, setActiveTab] = useState<'config' | 'templates'>('config')
  const [editingConfig, setEditingConfig] = useState<ConfigItem | null>(null)
  const [editingTemplate, setEditingTemplate] = useState<EmailTemplate | null>(null)
  const [configForm, setConfigForm] = useState({ value: '' })
  const [templateForm, setTemplateForm] = useState({ subject: '', body: '' })

  const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8086'
  const token = localStorage.getItem('kanban_token')

  useEffect(() => {
    fetchConfigs()
    fetchTemplates()
  }, [])

  const fetchConfigs = async () => {
    try {
      const response = await fetch(`${API_URL}/api/admin/config`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()
      if (data.success) {
        setConfigs(data.data)
      }
    } catch (err) {
      setError('获取配置失败')
    } finally {
      setLoading(false)
    }
  }

  const fetchTemplates = async () => {
    try {
      const response = await fetch(`${API_URL}/api/admin/email-templates`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()
      if (data.success) {
        setTemplates(data.data)
      }
    } catch (err) {
      console.error('获取邮件模板失败:', err)
    }
  }

  const handleConfigEdit = (config: ConfigItem) => {
    setEditingConfig(config)
    setConfigForm({ value: config.config_value })
  }

  const handleConfigSave = async () => {
    if (!editingConfig) return

    try {
      const response = await fetch(`${API_URL}/api/admin/config/${editingConfig.config_key}`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ value: configForm.value })
      })
      const data = await response.json()

      if (data.success) {
        fetchConfigs()
        setEditingConfig(null)
      } else {
        alert(data.error || '保存失败')
      }
    } catch (err) {
      alert('网络错误')
    }
  }

  const handleTemplateEdit = (template: EmailTemplate) => {
    setEditingTemplate(template)
    setTemplateForm({ subject: template.subject, body: template.body })
  }

  const handleTemplateSave = async () => {
    if (!editingTemplate) return

    try {
      const response = await fetch(`${API_URL}/api/admin/email-templates/${editingTemplate.id}`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(templateForm)
      })
      const data = await response.json()

      if (data.success) {
        fetchTemplates()
        setEditingTemplate(null)
      } else {
        alert(data.error || '保存失败')
      }
    } catch (err) {
      alert('网络错误')
    }
  }

  const getTypeBadge = (type: string) => {
    const colors: Record<string, string> = {
      string: '#3b82f6',
      int: '#10b981',
      float: '#f59e0b',
      bool: '#8b5cf6',
      json: '#ef4444'
    }
    return (
      <span 
        className="type-badge"
        style={{ backgroundColor: colors[type] || '#6b7280' }}
      >
        {type}
      </span>
    )
  }

  if (loading) return <div className="admin-loading">加载中...</div>
  if (error) return <div className="admin-error">{error}</div>

  return (
    <div className="system-config">
      <h1>系统配置</h1>

      {/* 标签页 */}
      <div className="tabs">
        <button 
          className={`tab ${activeTab === 'config' ? 'active' : ''}`}
          onClick={() => setActiveTab('config')}
        >
          参数配置
        </button>
        <button 
          className={`tab ${activeTab === 'templates' ? 'active' : ''}`}
          onClick={() => setActiveTab('templates')}
        >
          邮件模板
        </button>
      </div>

      {/* 参数配置 */}
      {activeTab === 'config' && (
        <div className="config-section">
          <table className="admin-table config-table">
            <thead>
              <tr>
                <th>配置键</th>
                <th>类型</th>
                <th>值</th>
                <th>描述</th>
                <th>更新时间</th>
                <th>操作</th>
              </tr>
            </thead>
            <tbody>
              {configs.map(config => (
                <tr key={config.id}>
                  <td className="config-key">{config.config_key}</td>
                  <td>{getTypeBadge(config.config_type)}</td>
                  <td className="config-value">
                    {config.config_value.length > 50 
                      ? config.config_value.substring(0, 50) + '...' 
                      : config.config_value}
                  </td>
                  <td>{config.description || '-'}</td>
                  <td>{new Date(config.updated_at).toLocaleString()}</td>
                  <td>
                    <button 
                      className="btn-icon"
                      onClick={() => handleConfigEdit(config)}
                      title="编辑"
                    >
                      ✏️
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* 邮件模板 */}
      {activeTab === 'templates' && (
        <div className="templates-section">
          <div className="templates-grid">
            {templates.map(template => (
              <div key={template.id} className="template-card">
                <div className="template-header">
                  <h3>{template.template_name}</h3>
                  <span className={`status-badge ${template.is_active ? 'active' : 'inactive'}`}>
                    {template.is_active ? '启用' : '禁用'}
                  </span>
                </div>
                <div className="template-info">
                  <p><strong>主题:</strong> {template.subject}</p>
                  <p><strong>变量:</strong> {template.variables.join(', ') || '无'}</p>
                  <p className="template-preview">
                    {template.body.substring(0, 100)}...
                  </p>
                </div>
                <div className="template-actions">
                  <button 
                    className="btn-primary"
                    onClick={() => handleTemplateEdit(template)}
                  >
                    编辑模板
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 配置编辑弹窗 */}
      {editingConfig && (
        <div className="modal-overlay" onClick={() => setEditingConfig(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>编辑配置</h2>
              <button className="btn-close" onClick={() => setEditingConfig(null)}>×</button>
            </div>
            <div className="modal-body">
              <div className="form-group">
                <label>配置键</label>
                <input type="text" value={editingConfig.config_key} disabled />
              </div>
              <div className="form-group">
                <label>类型</label>
                <input type="text" value={editingConfig.config_type} disabled />
              </div>
              <div className="form-group">
                <label>值</label>
                {editingConfig.config_type === 'bool' ? (
                  <select 
                    value={configForm.value}
                    onChange={(e) => setConfigForm({ value: e.target.value })}
                  >
                    <option value="true">true</option>
                    <option value="false">false</option>
                  </select>
                ) : editingConfig.config_type === 'json' ? (
                  <textarea
                    value={configForm.value}
                    onChange={(e) => setConfigForm({ value: e.target.value })}
                    rows={10}
                  />
                ) : (
                  <input 
                    type={editingConfig.config_type === 'int' || editingConfig.config_type === 'float' ? 'number' : 'text'}
                    value={configForm.value}
                    onChange={(e) => setConfigForm({ value: e.target.value })}
                  />
                )}
              </div>
              <div className="form-group">
                <label>描述</label>
                <input type="text" value={editingConfig.description || ''} disabled />
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn-secondary" onClick={() => setEditingConfig(null)}>
                取消
              </button>
              <button className="btn-primary" onClick={handleConfigSave}>
                保存
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 模板编辑弹窗 */}
      {editingTemplate && (
        <div className="modal-overlay" onClick={() => setEditingTemplate(null)}>
          <div className="modal-content wide" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>编辑邮件模板</h2>
              <button className="btn-close" onClick={() => setEditingTemplate(null)}>×</button>
            </div>
            <div className="modal-body">
              <div className="form-group">
                <label>模板名称</label>
                <input type="text" value={editingTemplate.template_name} disabled />
              </div>
              <div className="form-group">
                <label>主题</label>
                <input 
                  type="text" 
                  value={templateForm.subject}
                  onChange={(e) => setTemplateForm({ ...templateForm, subject: e.target.value })}
                />
              </div>
              <div className="form-group">
                <label>可用变量: {editingTemplate.variables.join(', ')}</label>
              </div>
              <div className="form-group">
                <label>内容 (HTML)</label>
                <textarea
                  value={templateForm.body}
                  onChange={(e) => setTemplateForm({ ...templateForm, body: e.target.value })}
                  rows={15}
                  className="code-editor"
                />
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn-secondary" onClick={() => setEditingTemplate(null)}>
                取消
              </button>
              <button className="btn-primary" onClick={handleTemplateSave}>
                保存
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
