import { useState, useEffect } from 'react'
import { Calendar, Smile, Frown, Meh, TrendingUp, Plus, Edit2, Trash2, Save, X } from 'lucide-react'

interface DailyReview {
  id: string
  date: string
  mood: 'great' | 'good' | 'neutral' | 'bad' | 'terrible'
  completed: string
  problems: string
  tomorrowPlan: string
  summary: string
}

const moodOptions = [
  { value: 'great', label: '棒极了', icon: Smile, color: '#22c55e' },
  { value: 'good', label: '不错', icon: Smile, color: '#84cc16' },
  { value: 'neutral', label: '一般', icon: Meh, color: '#eab308' },
  { value: 'bad', label: '不太好', icon: Frown, color: '#f97316' },
  { value: 'terrible', label: '糟糕', icon: Frown, color: '#ef4444' }
]

const defaultReviews: DailyReview[] = [
  {
    id: '1',
    date: '2026-03-08',
    mood: 'good',
    completed: '完成了看板3.0的4个模块重构',
    problems: '子代理代码质量问题需要解决',
    tomorrowPlan: '继续修复剩余模块',
    summary: '整体进展良好'
  }
]

export function DailyReviews() {
  const [reviews, setReviews] = useState<DailyReview[]>(defaultReviews)
  const [showModal, setShowModal] = useState(false)
  const [editingReview, setEditingReview] = useState<DailyReview | null>(null)
  const [formData, setFormData] = useState<Partial<DailyReview>>({
    date: new Date().toISOString().split('T')[0],
    mood: 'neutral',
    completed: '',
    problems: '',
    tomorrowPlan: '',
    summary: ''
  })

  const handleSave = () => {
    if (!formData.date) return
    
    if (editingReview) {
      setReviews(reviews.map(r => r.id === editingReview.id ? { ...r, ...formData } as DailyReview : r))
    } else {
      const newReview: DailyReview = {
        id: Date.now().toString(),
        date: formData.date,
        mood: formData.mood as DailyReview['mood'],
        completed: formData.completed || '',
        problems: formData.problems || '',
        tomorrowPlan: formData.tomorrowPlan || '',
        summary: formData.summary || ''
      }
      setReviews([newReview, ...reviews])
    }
    
    setShowModal(false)
    setEditingReview(null)
    setFormData({
      date: new Date().toISOString().split('T')[0],
      mood: 'neutral',
      completed: '',
      problems: '',
      tomorrowPlan: '',
      summary: ''
    })
  }

  const handleDelete = (id: string) => {
    if (confirm('确定要删除这条复盘吗？')) {
      setReviews(reviews.filter(r => r.id !== id))
    }
  }

  const openEdit = (review: DailyReview) => {
    setEditingReview(review)
    setFormData(review)
    setShowModal(true)
  }

  const getMoodOption = (mood: string) => moodOptions.find(m => m.value === mood) || moodOptions[2]

  // 统计
  const totalReviews = reviews.length
  const streak = calculateStreak(reviews)
  const avgMood = reviews.length > 0 
    ? reviews.reduce((sum, r) => moodOptions.findIndex(m => m.value === r.mood), 0) / reviews.length
    : 0

  function calculateStreak(reviews: DailyReview[]) {
    if (reviews.length === 0) return 0
    const sorted = [...reviews].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    let streak = 1
    for (let i = 1; i < sorted.length; i++) {
      const prev = new Date(sorted[i - 1].date)
      const curr = new Date(sorted[i].date)
      const diff = (prev.getTime() - curr.getTime()) / (1000 * 60 * 60 * 24)
      if (diff === 1) streak++
      else break
    }
    return streak
  }

  return (
    <div>
      <div className="page-header">
        <h2 className="page-title">📝 每日复盘</h2>
        <button
          onClick={() => {
            setEditingReview(null)
            setFormData({
              date: new Date().toISOString().split('T')[0],
              mood: 'neutral',
              completed: '',
              problems: '',
              tomorrowPlan: '',
              summary: ''
            })
            setShowModal(true)
          }}
          style={{
            padding: '10px 20px',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            gap: '8px'
          }}
        >
          <Plus size={18} />
          写复盘
        </button>
      </div>

      {/* 统计卡片 */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
        gap: '16px',
        marginBottom: '24px'
      }}>
        <div className="card" style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '2rem', fontWeight: 600, color: '#667eea' }}>{totalReviews}</div>
          <div style={{ color: '#666', fontSize: '0.9rem' }}>总复盘数</div>
        </div>
        <div className="card" style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '2rem', fontWeight: 600, color: '#11998e' }}>{streak}</div>
          <div style={{ color: '#666', fontSize: '0.9rem' }}>连续天数</div>
        </div>
        <div className="card" style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '2rem', fontWeight: 600, color: '#f59e0b' }}>
            {avgMood.toFixed(1)}
          </div>
          <div style={{ color: '#666', fontSize: '0.9rem' }}>平均心情</div>
        </div>
      </div>

      {/* 复盘列表 */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        {reviews.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(review => {
          const mood = getMoodOption(review.mood)
          const MoodIcon = mood.icon
          
          return (
            <div
              key={review.id}
              className="card"
              style={{
                borderLeft: '4px solid ' + mood.color
              }}
            >
              <div style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'flex-start',
                marginBottom: '16px'
              }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                  <div style={{
                    width: '40px',
                    height: '40px',
                    borderRadius: '50%',
                    background: mood.color + '20',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                  }}>
                    <MoodIcon size={20} color={mood.color} />
                  </div>
                  <div>
                    <div style={{ fontWeight: 600, fontSize: '1.1rem' }}>
                      {new Date(review.date).toLocaleDateString('zh-CN', {
                        month: 'long',
                        day: 'numeric',
                        weekday: 'short'
                      })}
                    </div>
                    <div style={{ color: mood.color, fontSize: '0.85rem' }}>
                      {mood.label}
                    </div>
                  </div>
                </div>
                <div style={{ display: 'flex', gap: '8px' }}>
                  <button
                    onClick={() => openEdit(review)}
                    style={{
                      padding: '6px',
                      background: 'none',
                      border: 'none',
                      cursor: 'pointer',
                      color: '#667eea'
                    }}
                  >
                    <Edit2 size={16} />
                  </button>
                  <button
                    onClick={() => handleDelete(review.id)}
                    style={{
                      padding: '6px',
                      background: 'none',
                      border: 'none',
                      cursor: 'pointer',
                      color: '#ef4444'
                    }}
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <div>
                  <h4 style={{ margin: '0 0 4px 0', color: '#22c55e', fontSize: '0.9rem' }}>
                    ✅ 今日完成
                  </h4>
                  <p style={{ margin: 0, color: '#666' }}>{review.completed || '无'}</p>
                </div>

                <div>
                  <h4 style={{ margin: '0 0 4px 0', color: '#f97316', fontSize: '0.9rem' }}>
                    ⚠️ 遇到的问题
                  </h4>
                  <p style={{ margin: 0, color: '#666' }}>{review.problems || '无'}</p>
                </div>

                <div>
                  <h4 style={{ margin: '0 0 4px 0', color: '#3b82f6', fontSize: '0.9rem' }}>
                    📋 明日计划
                  </h4>
                  <p style={{ margin: 0, color: '#666' }}>{review.tomorrowPlan || '无'}</p>
                </div>

                {review.summary && (
                  <div style={{
                    padding: '12px',
                    background: '#f8f9fa',
                    borderRadius: '8px',
                    marginTop: '8px'
                  }}>
                    <h4 style={{ margin: '0 0 4px 0', color: '#8b5cf6', fontSize: '0.9rem' }}>
                      💭 总结
                    </h4>
                    <p style={{ margin: 0, color: '#666' }}>{review.summary}</p>
                  </div>
                )}
              </div>
            </div>
          )
        })}
      </div>

      {reviews.length === 0 && (
        <div style={{
          textAlign: 'center',
          padding: '60px 20px',
          color: '#999'
        }}>
          <TrendingUp size={48} style={{ marginBottom: '16px', opacity: 0.5 }} />
          <p>还没有复盘记录，开始写第一条吧</p>
        </div>
      )}

      {/* 编辑弹窗 */}
      {showModal && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000
          }}
          onClick={() => setShowModal(false)}
        >
          <div
            style={{
              background: 'white',
              borderRadius: '12px',
              padding: '24px',
              width: '90%',
              maxWidth: '600px',
              maxHeight: '80vh',
              overflow: 'auto'
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 style={{ marginBottom: '20px' }}>
              {editingReview ? '编辑复盘' : '写复盘'}
            </h3>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  日期
                </label>
                <input
                  type="date"
                  value={formData.date}
                  onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px'
                  }}
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  今日心情
                </label>
                <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                  {moodOptions.map((option) => {
                    const Icon = option.icon
                    return (
                      <button
                        key={option.value}
                        onClick={() => setFormData({ ...formData, mood: option.value as DailyReview['mood'] })}
                        style={{
                          padding: '8px 12px',
                          background: formData.mood === option.value ? option.color : '#f0f0f0',
                          color: formData.mood === option.value ? 'white' : '#666',
                          border: 'none',
                          borderRadius: '8px',
                          cursor: 'pointer',
                          display: 'flex',
                          alignItems: 'center',
                          gap: '6px'
                        }}
                      >
                        <Icon size={16} />
                        {option.label}
                      </button>
                    )
                  })}
                </div>
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  今日完成
                </label>
                <textarea
                  value={formData.completed}
                  onChange={(e) => setFormData({ ...formData, completed: e.target.value })}
                  placeholder="今天完成了什么？"
                  rows={3}
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px',
                    resize: 'vertical'
                  }}
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  遇到的问题
                </label>
                <textarea
                  value={formData.problems}
                  onChange={(e) => setFormData({ ...formData, problems: e.target.value })}
                  placeholder="遇到了什么问题？"
                  rows={3}
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px',
                    resize: 'vertical'
                  }}
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  明日计划
                </label>
                <textarea
                  value={formData.tomorrowPlan}
                  onChange={(e) => setFormData({ ...formData, tomorrowPlan: e.target.value })}
                  placeholder="明天计划做什么？"
                  rows={3}
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px',
                    resize: 'vertical'
                  }}
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  总结
                </label>
                <textarea
                  value={formData.summary}
                  onChange={(e) => setFormData({ ...formData, summary: e.target.value })}
                  placeholder="今天的总结（可选）"
                  rows={2}
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px',
                    resize: 'vertical'
                  }}
                />
              </div>
            </div>

            <div style={{
              display: 'flex',
              gap: '12px',
              justifyContent: 'flex-end',
              marginTop: '24px'
            }}>
              <button
                onClick={() => setShowModal(false)}
                style={{
                  padding: '10px 20px',
                  background: '#f0f0f0',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px'
                }}
              >
                <X size={16} />
                取消
              </button>
              <button
                onClick={handleSave}
                disabled={!formData.date}
                style={{
                  padding: '10px 20px',
                  background: !formData.date ? '#ccc' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: !formData.date ? 'not-allowed' : 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px'
                }}
              >
                <Save size={16} />
                保存
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
