// ============================================
// 类型定义
// ============================================
type SkillLevel = 'beginner' | 'intermediate' | 'advanced' | 'expert'
type SkillCategory = 'technical' | 'soft' | 'language' | 'management' | 'creative' | 'analytical'
type ViewMode = 'grid' | 'tree' | 'path'

interface LearningResource {
  id: string
  title: string
  url: string
  type: 'article' | 'video' | 'course' | 'book' | 'documentation'
}

interface Certificate {
  id: string
  name: string
  issuer: string
  issueDate: string
  expiryDate?: string
  credentialId?: string
  url?: string
  fileUrl?: string
}

interface Skill {
  id: string
  name: string
  description: string
  category: SkillCategory
  level: SkillLevel
  progress: number // 0-100
  rating: number // 1-5
  icon: string
  color: string
  parentSkills?: string[] // 依赖的技能ID
  childSkills?: string[] // 被依赖的技能ID
  resources: LearningResource[]
  certificates: Certificate[]
  estimatedHours: number
  completedHours: number
  lastPracticed?: string
  tags: string[]
}

interface SkillStats {
  total: number
  byCategory: Record<SkillCategory, number>
  byLevel: Record<SkillLevel, number>
  averageProgress: number
  totalCertificates: number
  totalResources: number
  totalHoursLearned: number
}

