import { useState, useEffect, useMemo } from 'react'
import { useNavigate, useSearchParams } from 'react-router-dom'
import {
  Calendar, Users, FileText, CheckSquare, Search, Plus, Grid, List, Filter,
  Download, Edit3, Trash2, Clock, MapPin, Tag, ChevronLeft, ChevronRight,
  CheckCircle2, Circle, X, Save, MoreVertical, ExternalLink, Archive
} from 'lucide-react'

// ==================== Type Definitions ====================

interface TodoItem {
  id: string
  content: string
  assignee?: string
  completed: boolean
  deadline?: string
}

interface Meeting {
  id: string
  title: string
  date: string
  time: string
  location?: string
  project?: string
  type?: string
  attendees: string[]
  agenda: string
  content: string
  conclusion?: string
  todos: TodoItem[]
  tags: string[]
  createdAt: string
  updatedAt: string
}

interface MeetingFilter {
  project?: string
  type?: string
  dateFrom?: string
  dateTo?: string
  status?: 'all' | 'upcoming' | 'past'
}

// ==================== Utility Functions ====================

const generateId = () => Math.random().toString(36).substring(2, 15)

const formatDate = (dateStr: string) => {
  if (!dateStr) return ''
  const date = new Date(dateStr)
  return date.toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'short' })
}

const formatDateTime = (dateStr: string, timeStr: string) => {
  if (!dateStr) return ''
  const date = new Date(`${dateStr}T${timeStr || '00:00'}`)
  return date.toLocaleString('zh-CN', { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
}

const isUpcoming = (dateStr: string, timeStr: string) => {
  if (!dateStr) return false
  const meetingTime = new Date(`${dateStr}T${timeStr || '23:59'}`)
  return meetingTime > new Date()
}

const exportToMarkdown = (meeting: Meeting): string => {
  return `# ${meeting.title}

**日期**: ${formatDate(meeting.date)} ${meeting.time}  
**地点**: ${meeting.location || '待定'}  
**项目**: ${meeting.project || '未分类'}  
**类型**: ${meeting.type || '未指定'}

## 参与人员

${meeting.attendees.map(a => `- ${a}`).join('\n') || '- 暂无'}

## 会议议程

${meeting.agenda || '暂无议程'}

## 会议内容

${meeting.content || '暂无内容'}

## 会议结论

${meeting.conclusion || '暂无结论'}

## 待办事项

${meeting.todos.map(todo => `- [${todo.completed ? 'x' : ' '}] ${todo.content}${todo.assignee ? ` (@${todo.assignee})` : ''}${todo.deadline ? ` - 截止: ${todo.deadline}` : ''}`).join('\n') || '- 暂无待办'}

---
*导出时间: ${new Date().toLocaleString('zh-CN')}*`
}

const exportToText = (meeting: Meeting): string => {
  return `${meeting.title}
================================

日期: ${formatDate(meeting.date)} ${meeting.time}
地点: ${meeting.location || '待定'}
项目: ${meeting.project || '未分类'}
类型: ${meeting.type || '未指定'}

参与人员:
${meeting.attendees.map(a => `  - ${a}`).join('\n') || '  暂无'}

会议议程:
${meeting.agenda || '暂无议程'}

会议内容:
${meeting.content || '暂无内容'}

会议结论:
${meeting.conclusion || '暂无结论'}

待办事项:
${meeting.todos.map(todo => `  [${todo.completed ? '✓' : '○'}] ${todo.content}${todo.assignee ? ` (${todo.assignee})` : ''}${todo.deadline ? ` - ${todo.deadline}` : ''}`).join('\n') || '  暂无待办'}
`
}

