import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import './GoalProjectTask.css'

interface Goal {
  id: number
  title: string
  description: string
  status: string
  projects: Project[]
}

interface Project {
  id: number
  name: string
  description: string
  status: string
  goal_id: number
  tasks: Task[]
}

interface Task {
  id: number
  title: string
  status: string
  project_id: number
  priority: string
}

export function GoalProjectTask() {
  const [goals, setGoals] = useState<Goal[]>([])
  const [loading, setLoading] = useState(true)
  const [stats, setStats] = useState({ goals: 0, projects: 0, tasks: 0 })

  useEffect(() => {
    fetchHierarchy()
  }, [])

  const fetchHierarchy = async () => {
    try {
      // 获取目标列表
      const goalsRes = await fetch('/api/goals')
      const goalsData = await goalsRes.json()
      
      if (goalsData.success) {
        const goalsWithRelations = await Promise.all(
          goalsData.goals.map(async (goal: Goal) => {
            // 获取每个目标下的项目
            const projectsRes = await fetch(`/api/goals/${goal.id}/projects`)
            const projectsData = await projectsRes.json()
            
            if (projectsData.success) {
              const projectsWithTasks = await Promise.all(
                projectsData.projects.map(async (project: Project) => {
                  // 获取每个项目下的任务
                  const tasksRes = await fetch(`/api/projects/${project.id}/tasks`)
                  const tasksData = await tasksRes.json()
                  return {
                    ...project,
                    tasks: tasksData.success ? tasksData.tasks : []
                  }
                })
              )
              return { ...goal, projects: projectsWithTasks }
            }
            return { ...goal, projects: [] }
          })
        )
        
        setGoals(goalsWithRelations)
        
        // 计算统计
        const projectCount = goalsWithRelations.reduce(
          (sum, g) => sum + g.projects.length, 0
        )
        const taskCount = goalsWithRelations.reduce(
          (sum: number, g: Goal) => sum + g.projects.reduce((pSum: number, p: Project) => pSum + p.tasks.length, 0), 0
        )
        
        setStats({
          goals: goalsWithRelations.length,
          projects: projectCount,
          tasks: taskCount
        })
      }
    } catch (error) {
      console.error('Failed to fetch hierarchy:', error)
    } finally {
      setLoading(false)
    }
  }

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      'active': '#4CAF50',
      'completed': '#2196F3',
      'pending': '#FF9800',
      'archived': '#9E9E9E',
      'todo': '#9E9E9E',
      'in_progress': '#FF9800',
      'done': '#4CAF50'
    }
    return colors[status] || '#666'
  }

  if (loading) {
    return <div className="loading">加载层级结构中...</div>
  }

  return (
    <div className="goal-project-task-page">
      <div className="page-header">
        <h1>🎯 目标-项目-任务 层级视图</h1>
        <p>清晰展现战略目标、项目执行与任务分解的完整关系</p>
      </div>

      {/* 统计卡片 */}
      <div className="stats-cards">
        <div className="stat-card goal">
          <div className="stat-icon">🎯</div>
          <div className="stat-content">
            <div className="stat-number">{stats.goals}</div>
            <div className="stat-label">目标</div>
          </div>
        </div>
        <div className="stat-card project">
          <div className="stat-icon">📁</div>
          <div className="stat-content">
            <div className="stat-number">{stats.projects}</div>
            <div className="stat-label">项目</div>
          </div>
        </div>
        <div className="stat-card task">
          <div className="stat-icon">✅</div>
          <div className="stat-content">
            <div className="stat-number">{stats.tasks}</div>
            <div className="stat-label">任务</div>
          </div>
        </div>
      </div>

      {/* 层级结构展示 */}
      <div className="hierarchy-container">
        {goals.length === 0 ? (
          <div className="empty-state">
            <p>暂无目标数据</p>
            <Link to="/goals" className="btn btn-primary">创建第一个目标</Link>
          </div>
        ) : (
          goals.map(goal => (
            <div key={goal.id} className="goal-node">
              {/* 目标层级 */}
              <div className="node-card goal-level">
                <div className="node-header">
                  <span className="node-badge">目标</span>
                  <span 
                    className="node-status"
                    style={{ background: getStatusColor(goal.status) }}
                  >
                    {goal.status}
                  </span>
                </div>
                <h3 className="node-title">
                  <Link to={`/goals/${goal.id}`}>{goal.title}</Link>
                </h3>
                <p className="node-description">{goal.description}</p>
                <div className="node-meta">
                  <span>📁 {goal.projects.length} 个项目</span>
                </div>
              </div>

              {/* 连接线 */}
              {goal.projects.length > 0 && (
                <div className="connection-line"></div>
              )}

              {/* 项目层级 */}
              <div className="projects-container">
                {goal.projects.map(project => (
                  <div key={project.id} className="project-branch">
                    <div className="node-card project-level">
                      <div className="node-header">
                        <span className="node-badge">项目</span>
                        <span 
                          className="node-status"
                          style={{ background: getStatusColor(project.status) }}
                        >
                          {project.status}
                        </span>
                      </div>
                      <h4 className="node-title">
                        <Link to={`/projects/${project.id}`}>{project.name}</Link>
                      </h4>
                      <p className="node-description">{project.description}</p>
                      <div className="node-meta">
                        <span>✅ {project.tasks.length} 个任务</span>
                      </div>
                    </div>

                    {/* 连接线 */}
                    {project.tasks.length > 0 && (
                      <div className="connection-line sub"></div>
                    )}

                    {/* 任务层级 */}
                    <div className="tasks-container">
                      {project.tasks.map(task => (
                        <div key={task.id} className="node-card task-level">
                          <div className="node-header">
                            <span className="node-badge">任务</span>
                            <span 
                              className="node-status"
                              style={{ background: getStatusColor(task.status) }}
                            >
                              {task.status}
                            </span>
                          </div>
                          <h5 className="node-title">
                            <Link to={`/tasks/${task.id}`}>{task.title}</Link>
                          </h5>
                          <div className="node-meta">
                            <span style={{ 
                              color: task.priority === 'high' ? '#f44336' : 
                                     task.priority === 'medium' ? '#ff9800' : '#4caf50'
                            }}>
                              优先级: {task.priority}
                            </span>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))
        )}
      </div>

      {/* 快速操作 */}
      <div className="quick-actions">
        <h3>快速操作</h3>
        <div className="action-buttons">
          <Link to="/goals" className="action-btn">
            <span className="icon">🎯</span>
            <span>管理目标</span>
          </Link>
          <Link to="/projects" className="action-btn">
            <span className="icon">📁</span>
            <span>管理项目</span>
          </Link>
          <Link to="/tasks" className="action-btn">
            <span className="icon">✅</span>
            <span>管理任务</span>
          </Link>
        </div>
      </div>
    </div>
  )
}
