// 可展开的侧边栏菜单组件
function SidebarMenu({ items, sidebarOpen, location }: { 
  items: MenuItem[]
  sidebarOpen: boolean
  location: any
}) {
  const [expandedItems, setExpandedItems] = useState<string[]>(['目标-项目-任务'])

  const toggleExpand = (label: string) => {
    setExpandedItems(prev => 
      prev.includes(label) 
        ? prev.filter(item => item !== label)
        : [...prev, label]
    )
  }

  const isActive = (path: string) => location.pathname === path
  const isChildActive = (children?: MenuItem[]) => 
    children?.some(child => child.path && isActive(child.path))

  return (
    <>
      {items.map(item => {
        if (item.isExpandable && item.children) {
          const isExpanded = expandedItems.includes(item.label)
          const hasActiveChild = isChildActive(item.children)
          
          return (
            <div key={item.label} className="nav-group">
              <div 
                className={`nav-item nav-group-header ${hasActiveChild ? 'active' : ''}`}
                onClick={() => sidebarOpen && toggleExpand(item.label)}
                style={{ cursor: sidebarOpen ? 'pointer' : 'default' }}
              >
                <span className="nav-icon">{item.icon}</span>
                {sidebarOpen && (
                  <>
                    <span className="nav-label">{item.label}</span>
                    <span className="nav-expand-icon" style={{ 
                      marginLeft: 'auto',
                      transform: isExpanded ? 'rotate(90deg)' : 'rotate(0deg)',
                      transition: 'transform 0.2s'
                    }}>
                      ▶
                    </span>
                  </>
                )}
              </div>
              {sidebarOpen && isExpanded && (
                <div className="nav-children" style={{ 
                  paddingLeft: '20px',
                  borderLeft: '2px solid #e0e0e0',
                  marginLeft: '20px'
                }}>
                  {item.children.map(child => (
                    <Link
                      key={child.path}
                      to={child.path!}
                      className={`nav-item ${isActive(child.path!) ? 'active' : ''}`}
                      style={{ fontSize: '0.9rem' }}
                    >
                      <span className="nav-icon">{child.icon}</span>
                      <span className="nav-label">{child.label}</span>
                    </Link>
                  ))}
                </div>
              )}
            </div>
          )
        }

        return (
          <Link
            key={item.path}
            to={item.path!}
            className={`nav-item ${isActive(item.path!) ? 'active' : ''}`}
          >
            <span className="nav-icon">{item.icon}</span>
            {sidebarOpen && <span className="nav-label">{item.label}</span>}
          </Link>
        )
      })}
    </>
  )
}

