import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'

// 图标组件
const SyncIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
    <path d="M21.5 2v6h-6M2.5 22v-6h6M2 11.5a10 10 0 0 1 18.8-4.3M22 12.5a10 10 0 0 1-18.8 4.3"/>
  </svg>
)

const PlusIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
    <line x1="12" y1="5" x2="12" y2="19"/>
    <line x1="5" y1="12" x2="19" y2="12"/>
  </svg>
)

const TrashIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
    <polyline points="3 6 5 6 21 6"/>
    <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>
  </svg>
)

const BackIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
    <polyline points="15 18 9 12 15 6"/>
  </svg>
)

export function CalendarSettings() {
  const navigate = useNavigate()
  const [accounts, setAccounts] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [syncing, setSyncing] = useState(false)
  const [saving, setSaving] = useState(false)
  const [showAddModal, setShowAddModal] = useState(false)
  
  // 设置状态
  const [settings, setSettings] = useState({
    default_view: 'month',
    first_day_of_week: 0,
    show_weekends: true,
    working_hours_start: '09:00',
    working_hours_end: '18:00',
    default_reminder_minutes: 15,
    enable_notifications: true,
    notification_sound: true,
    sync_enabled: false,
    sync_interval_minutes: 30,
    default_calendar_color: '#667eea'
  })
  
  const [formData, setFormData] = useState({
    name: '',
    account_type: 'caldav',
    server_url: '',
    username: '',
    password: '',
    calendar_name: ''
  })

  useEffect(() => {
    loadSettings()
    loadAccounts()
  }, [])

  const loadSettings = async () => {
    try {
      const res = await fetch('/api/calendar/settings')
      const data = await res.json()
      if (data.success && data.settings) {
        setSettings(data.settings)
      }
    } catch (e) {
      console.error('Failed to load settings:', e)
    }
  }

  const loadAccounts = async () => {
    try {
      const res = await fetch('/api/calendar/accounts')
      const data = await res.json()
      if (data.success) setAccounts(data.accounts || [])
    } catch (e) {
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  const saveSettings = async () => {
    setSaving(true)
    try {
      const res = await fetch('/api/calendar/settings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings)
      })
      const data = await res.json()
      if (data.success) {
        alert('设置已保存')
      }
    } catch (e) {
      alert('保存失败')
    } finally {
      setSaving(false)
    }
  }

  const handleSync = async () => {
    setSyncing(true)
    try {
      const res = await fetch('/api/calendar/sync', { method: 'POST' })
      const data = await res.json()
      if (data.success) {
        alert(`同步完成！共同步 ${data.results?.reduce((acc: number, r: any) => acc + (r.synced_events || 0), 0)} 个事件`)
        loadAccounts()
      } else {
        alert('同步失败: ' + data.error)
      }
    } catch (e) {
      alert('同步出错')
    } finally {
      setSyncing(false)
    }
  }

  const handleAddAccount = async (e: React.FormEvent) => {
    e.preventDefault()
    try {
      const res = await fetch('/api/calendar/accounts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      })
      const data = await res.json()
      if (data.success) {
        setShowAddModal(false)
        setFormData({ name: '', account_type: 'caldav', server_url: '', username: '', password: '', calendar_name: '' })
        loadAccounts()
      }
    } catch (e) {
      console.error(e)
    }
  }

  const viewModes = [
    { value: 'month', label: '月视图' },
    { value: 'week', label: '周视图' },
    { value: 'day', label: '日视图' }
  ]

  const weekStartDays = [
    { value: 0, label: '周日' },
    { value: 1, label: '周一' }
  ]

  const reminderOptions = [
    { value: 0, label: '不提醒' },
    { value: 5, label: '5分钟前' },
    { value: 10, label: '10分钟前' },
    { value: 15, label: '15分钟前' },
    { value: 30, label: '30分钟前' },
    { value: 60, label: '1小时前' },
    { value: 1440, label: '1天前' }
  ]

  const syncIntervals = [
    { value: 15, label: '15分钟' },
    { value: 30, label: '30分钟' },
    { value: 60, label: '1小时' },
    { value: 120, label: '2小时' },
    { value: 360, label: '6小时' },
    { value: 720, label: '12小时' },
    { value: 1440, label: '1天' }
  ]

  if (loading) return <div className="loading">加载中...</div>

  return (
    <div style={{ padding: '20px' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
        <h2>⚙️ 日历设置</h2>
        <div style={{ display: 'flex', gap: '12px' }}>
          <button className="btn btn-secondary" onClick={() => navigate('/calendar')}>
            <BackIcon /> 返回日历
          </button>
          <button className="btn btn-primary" onClick={saveSettings} disabled={saving}>
            {saving ? '保存中...' : '💾 保存设置'}
          </button>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '24px' }}>
        {/* 视图设置 */}
        <div className="card">
          <div className="card-header">
            <h5 style={{ color: '#667eea' }}>📐 视图偏好</h5>
          </div>
          <div style={{ padding: '20px' }}>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '8px', fontWeight: 500 }}>默认视图</label>
              <select
                value={settings.default_view}
                onChange={e => setSettings({...settings, default_view: e.target.value})}
                style={{ width: '100%', padding: '10px' }}
              >
                {viewModes.map(mode => (
                  <option key={mode.value} value={mode.value}>{mode.label}</option>
                ))}
              </select>
            </div>

            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '8px', fontWeight: 500 }}>每周开始于</label>
              <select
                value={settings.first_day_of_week}
                onChange={e => setSettings({...settings, first_day_of_week: parseInt(e.target.value)})}
                style={{ width: '100%', padding: '10px' }}
              >
                {weekStartDays.map(day => (
                  <option key={day.value} value={day.value}>{day.label}</option>
                ))}
              </select>
            </div>

            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer' }}>
                <input
                  type="checkbox"
                  checked={settings.show_weekends}
                  onChange={e => setSettings({...settings, show_weekends: e.target.checked})}
                />
                显示周末
              </label>
            </div>

            <div>
              <label style={{ display: 'block', marginBottom: '8px', fontWeight: 500 }}>默认日历颜色</label>
              <input
                type="color"
                value={settings.default_calendar_color}
                onChange={e => setSettings({...settings, default_calendar_color: e.target.value})}
                style={{ width: '60px', height: '40px', border: 'none', borderRadius: '6px' }}
              />
            </div>
          </div>
        </div>

        {/* 工作时间设置 */}
        <div className="card">
          <div className="card-header">
            <h5 style={{ color: '#4facfe' }}>⏰ 工作时间</h5>
          </div>
          <div style={{ padding: '20px' }}>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '8px', fontWeight: 500 }}>开始时间</label>
              <input
                type="time"
                value={settings.working_hours_start}
                onChange={e => setSettings({...settings, working_hours_start: e.target.value})}
                style={{ width: '100%', padding: '10px' }}
              />
            </div>

            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '8px', fontWeight: 500 }}>结束时间</label>
              <input
                type="time"
                value={settings.working_hours_end}
                onChange={e => setSettings({...settings, working_hours_end: e.target.value})}
                style={{ width: '100%', padding: '10px' }}
              />
            </div>

            <div>
              <label style={{ display: 'block', marginBottom: '8px', fontWeight: 500 }}>默认提醒时间</label>
              <select
                value={settings.default_reminder_minutes}
                onChange={e => setSettings({...settings, default_reminder_minutes: parseInt(e.target.value)})}
                style={{ width: '100%', padding: '10px' }}
              >
                {reminderOptions.map(opt => (
                  <option key={opt.value} value={opt.value}>{opt.label}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* 通知设置 */}
        <div className="card">
          <div className="card-header">
            <h5 style={{ color: '#f093fb' }}>🔔 通知设置</h5>
          </div>
          <div style={{ padding: '20px' }}>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer' }}>
                <input
                  type="checkbox"
                  checked={settings.enable_notifications}
                  onChange={e => setSettings({...settings, enable_notifications: e.target.checked})}
                />
                启用通知
              </label>
            </div>

            <div>
              <label style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer' }}>
                <input
                  type="checkbox"
                  checked={settings.notification_sound}
                  onChange={e => setSettings({...settings, notification_sound: e.target.checked})}
                  disabled={!settings.enable_notifications}
                />
                通知声音
              </label>
            </div>
          </div>
        </div>

        {/* 同步设置 */}
        <div className="card">
          <div className="card-header">
            <h5 style={{ color: '#38ef7d' }}>🔄 同步设置</h5>
          </div>
          <div style={{ padding: '20px' }}>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer' }}>
                <input
                  type="checkbox"
                  checked={settings.sync_enabled}
                  onChange={e => setSettings({...settings, sync_enabled: e.target.checked})}
                />
                启用自动同步
              </label>
            </div>

            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '8px', fontWeight: 500 }}>同步间隔</label>
              <select
                value={settings.sync_interval_minutes}
                onChange={e => setSettings({...settings, sync_interval_minutes: parseInt(e.target.value)})}
                disabled={!settings.sync_enabled}
                style={{ width: '100%', padding: '10px' }}
              >
                {syncIntervals.map(opt => (
                  <option key={opt.value} value={opt.value}>{opt.label}</option>
                ))}
              </select>
            </div>

            <button 
              onClick={handleSync} 
              disabled={syncing}
              className="btn btn-success"
              style={{ width: '100%' }}
            >
              <SyncIcon /> {syncing ? '同步中...' : '立即同步'}
            </button>
          </div>
        </div>
      </div>

      {/* CalDAV账户管理 */}
      <div className="card">
        <div className="card-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h5 style={{ margin: 0, color: '#667eea' }}>☁️ CalDAV账户 ({accounts.length})</h5>
          <button className="btn btn-primary" onClick={() => setShowAddModal(true)}>
            <PlusIcon /> 添加账户
          </button>
        </div>
        <div className="table-container">
          <table className="data-table">
            <thead>
              <tr>
                <th>名称</th>
                <th>类型</th>
                <th>服务器</th>
                <th>用户名</th>
                <th>状态</th>
                <th>最后同步</th>
                <th>操作</th>
              </tr>
            </thead>
            <tbody>
              {accounts.length === 0 ? (
                <tr>
                  <td colSpan={7} className="empty-state">
                    <div>暂无CalDAV账户</div>
                    <div style={{ fontSize: '0.85rem', color: '#999', marginTop: '8px' }}>
                      点击"添加账户"配置iCloud/Google/Outlook日历同步
                    </div>
                  </td>
                </tr>
              ) : (
                accounts.map((account: any) => (
                  <tr key={account.id}>
                    <td><strong>{account.name}</strong></td>
                    <td>
                      <span className="badge badge-blue">{account.account_type?.toUpperCase()}</span>
                    </td>
                    <td style={{ fontSize: '0.85rem', maxWidth: '200px', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                      {account.server_url}
                    </td>
                    <td>{account.username}</td>
                    <td>
                      <span className={`badge ${account.sync_enabled ? 'badge-green' : 'badge-gray'}`}>
                        {account.sync_enabled ? '已启用' : '已禁用'}
                      </span>
                    </td>
                    <td style={{ fontSize: '0.85rem' }}>
                      {account.last_sync_at ? new Date(account.last_sync_at).toLocaleString('zh-CN') : '从未'}
                    </td>
                    <td>
                      <button className="btn btn-sm btn-danger">
                        <TrashIcon />
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* 配置说明 */}
      <div className="card" style={{ marginTop: '20px' }}>
        <div className="card-header">
          <h5>📖 配置指南</h5>
        </div>
        <div style={{ padding: '20px' }}>
          <h6 style={{ marginBottom: '12px' }}>支持的日历服务：</h6>
          <ul style={{ lineHeight: '2', paddingLeft: '20px', marginBottom: '20px' }}>
            <li><strong>iCloud日历</strong> - 使用App专用密码</li>
            <li><strong>Google日历</strong> - 启用CalDAV API</li>
            <li><strong>Outlook.com</strong> - 支持CalDAV协议</li>
            <li><strong>自建CalDAV服务器</strong> - 如Nextcloud、Radicale</li>
          </ul>
          
          <h6 style={{ marginBottom: '12px' }}>iCloud配置示例：</h6>
          <div style={{ background: '#f8f9fa', padding: '16px', borderRadius: '8px', fontFamily: 'monospace', fontSize: '0.85rem' }}>
            <div>服务器: https://caldav.icloud.com</div>
            <div>用户名: your@icloud.com</div>
            <div>密码: [App专用密码]</div>
          </div>
        </div>
      </div>

      {/* 添加账户弹窗 */}
      {showAddModal && (
        <div className="modal-overlay" onClick={() => setShowAddModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()} style={{ maxWidth: '500px' }}>
            <h3><PlusIcon /> 添加CalDAV账户</h3>
            <form onSubmit={handleAddAccount} style={{ marginTop: '16px' }}>
              <div style={{ marginBottom: '16px' }}>
                <label>账户名称 *</label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  placeholder="例如：我的iCloud"
                  required
                />
              </div>
              <div style={{ marginBottom: '16px' }}>
                <label>账户类型</label>
                <select
                  value={formData.account_type}
                  onChange={e => setFormData({...formData, account_type: e.target.value})}
                >
                  <option value="caldav">CalDAV (通用)</option>
                  <option value="icloud">iCloud</option>
                  <option value="google">Google</option>
                  <option value="outlook">Outlook</option>
                </select>
              </div>
              <div style={{ marginBottom: '16px' }}>
                <label>服务器地址 *</label>
                <input
                  type="url"
                  value={formData.server_url}
                  onChange={e => setFormData({...formData, server_url: e.target.value})}
                  placeholder="https://caldav.icloud.com"
                  required
                />
              </div>
              <div style={{ marginBottom: '16px' }}>
                <label>用户名 *</label>
                <input
                  type="text"
                  value={formData.username}
                  onChange={e => setFormData({...formData, username: e.target.value})}
                  placeholder="your@email.com"
                  required
                />
              </div>
              <div style={{ marginBottom: '16px' }}>
                <label>密码 *</label>
                <input
                  type="password"
                  value={formData.password}
                  onChange={e => setFormData({...formData, password: e.target.value})}
                  placeholder="密码或App专用密码"
                  required
                />
              </div>
              <div style={{ marginBottom: '24px' }}>
                <label>日历名称（可选）</label>
                <input
                  type="text"
                  value={formData.calendar_name}
                  onChange={e => setFormData({...formData, calendar_name: e.target.value})}
                  placeholder="工作 / 个人 / 家庭"
                />
              </div>
              <div className="modal-actions">
                <button type="button" className="btn btn-secondary" onClick={() => setShowAddModal(false)}>取消</button>
                <button type="submit" className="btn btn-success">添加账户</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}