import { useState, useEffect } from 'react'
import { api } from '../utils/api'

interface AuditTask {
  id: number
  task_type: string
  title: string
  description: string
  source: string
  status: 'pending' | 'approved' | 'rejected'
  priority: 'high' | 'medium' | 'low'
  notes?: string
  created_at: string
  completed_at?: string
  reviewer?: string
  is_from_long_think?: boolean
  source_id?: number
}

export function ManualReview() {
  const [tasks, setTasks] = useState<AuditTask[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<'pending' | 'completed' | 'all' | 'long_think'>('pending')
  const [selectedTask, setSelectedTask] = useState<AuditTask | null>(null)
  const [auditNotes, setAuditNotes] = useState('')
  const [showDetailModal, setShowDetailModal] = useState(false)

  useEffect(() => {
    loadTasks()
  }, [filter])

  const loadTasks = async () => {
    try {
      setLoading(true)
      const res = await api.getManualReviewTasks()
      if (res.success) {
        let filtered = res.tasks || []
        
        // 筛选逻辑
        if (filter === 'long_think') {
          filtered = filtered.filter((t: AuditTask) => t.is_from_long_think)
        } else if (filter !== 'all') {
          filtered = filtered.filter((t: AuditTask) => t.status === filter)
        }
        
        // 排序：高优先级在前，然后按创建时间倒序
        filtered.sort((a: AuditTask, b: AuditTask) => {
          const priorityOrder = { high: 0, medium: 1, low: 2 }
          if (priorityOrder[a.priority] !== priorityOrder[b.priority]) {
            return priorityOrder[a.priority] - priorityOrder[b.priority]
          }
          return new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
        })
        
        setTasks(filtered)
      }
    } catch (e) {
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  const handleApprove = async (taskId: number) => {
    const notes = auditNotes || '审核通过，可以执行'
    
    const res = await api.completeManualReviewTask(taskId, {
      approved: true,
      notes
    })

    if (res.success) {
      alert('✅ 任务已批准')
      setShowDetailModal(false)
      setAuditNotes('')
      loadTasks()
    } else {
      alert('❌ 操作失败: ' + (res.error || '未知错误'))
    }
  }

  const handleReject = async (taskId: number) => {
    const notes = auditNotes || '审核未通过'
    
    if (!confirm('确定要拒绝此任务吗？')) return
    
    const res = await api.completeManualReviewTask(taskId, {
      approved: false,
      notes
    })

    if (res.success) {
      alert('❌ 任务已拒绝')
      setShowDetailModal(false)
      setAuditNotes('')
      loadTasks()
    } else {
      alert('❌ 操作失败: ' + (res.error || '未知错误'))
    }
  }

  const openTaskDetail = (task: AuditTask) => {
    setSelectedTask(task)
    setAuditNotes('')
    setShowDetailModal(true)
  }

  const getTaskTypeLabel = (type: string) => {
    const labels: Record<string, string> = {
      'email': '📧 邮件',
      'task': '✅ 任务',
      'calculation': '🔢 计算',
      'deploy': '🚀 部署',
      'review': '👁️ 审核',
      'long_think': '🧠 长思考',
      'gear_system': '⚙️ 齿轮系统',
      'strategy_coordinator': '📊 战略协调员',
      'perception_agent': '👁️ 感知Agent'
    }
    return labels[type] || type
  }

  const getPriorityLabel = (priority: string) => {
    const labels: Record<string, { text: string, color: string }> = {
      'high': { text: '🔴 高优先级', color: '#ff4d4f' },
      'medium': { text: '🟡 中优先级', color: '#faad14' },
      'low': { text: '🟢 低优先级', color: '#52c41a' }
    }
    return labels[priority] || { text: priority, color: '#999' }
  }

  // 统计
  const allTasks = tasks
  const pendingTasks = allTasks.filter(t => t.status === 'pending')
  const longThinkTasks = allTasks.filter(t => t.is_from_long_think)
  const pendingLongThink = longThinkTasks.filter(t => t.status === 'pending')
  
  // 按优先级统计待审核
  const highPriorityPending = pendingTasks.filter(t => t.priority === 'high').length
  const mediumPriorityPending = pendingTasks.filter(t => t.priority === 'medium').length
  const lowPriorityPending = pendingTasks.filter(t => t.priority === 'low').length

  if (loading) return <div className="loading">加载中...</div>

  return (
    <div>
      <div className="page-header">
        <h2 className="page-title">👁️ 任务审核中心</h2>
      </div>

      {/* 统计卡片 */}
      <div style={{ 
        display: 'grid', 
        gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', 
        gap: '16px', 
        marginBottom: '20px' 
      }}>
        <div className="stat-card" style={{ padding: '20px', borderLeft: '4px solid #ff4d4f' }}>
          <div style={{ fontSize: '2rem', fontWeight: 600, color: '#ff4d4f' }}>{highPriorityPending}</div>
          <div style={{ fontSize: '0.9rem', color: '#666' }}>🔴 高优先级待审核</div>
        </div>
        <div className="stat-card" style={{ padding: '20px', borderLeft: '4px solid #faad14' }}>
          <div style={{ fontSize: '2rem', fontWeight: 600, color: '#faad14' }}>{mediumPriorityPending}</div>
          <div style={{ fontSize: '0.9rem', color: '#666' }}>🟡 中优先级待审核</div>
        </div>
        <div className="stat-card" style={{ padding: '20px', borderLeft: '4px solid #52c41a' }}>
          <div style={{ fontSize: '2rem', fontWeight: 600, color: '#52c41a' }}>{lowPriorityPending}</div>
          <div style={{ fontSize: '0.9rem', color: '#666' }}>🟢 低优先级待审核</div>
        </div>
        <div className="stat-card" style={{ padding: '20px', borderLeft: '4px solid #722ed1' }}>
          <div style={{ fontSize: '2rem', fontWeight: 600, color: '#722ed1' }}>{pendingLongThink.length}</div>
          <div style={{ fontSize: '0.9rem', color: '#666' }}>🧠 长思考待审核</div>
        </div>
      </div>

      {/* 防重复提示 */}
      {pendingLongThink.length > 0 && (
        <div style={{
          padding: '16px 20px',
          background: '#fff3e0',
          borderLeft: '4px solid #ff9800',
          borderRadius: '8px',
          marginBottom: '20px'
        }}>
          <strong>⚠️ 防重复机制提示：</strong>
          <p style={{ margin: '8px 0 0 0', color: '#666' }}>
            存在 {pendingLongThink.length} 个未执行的长思考任务。
            在这些任务被执行之前，系统不会再为同一任务生成新的长思考结果。
          </p>
        </div>
      )}

      {/* 筛选 */}
      <div className="filter-bar">
        {[
          { key: 'pending', label: `⏳ 待审核 (${pendingTasks.length})` },
          { key: 'completed', label: '✅ 已完成' },
          { key: 'all', label: '📋 全部' },
          { key: 'long_think', label: '🧠 长思考' }
        ].map(item => (
          <button
            key={item.key}
            className={`filter-btn ${filter === item.key ? 'active' : ''}`}
            onClick={() => setFilter(item.key as any)}
          >
            {item.label}
          </button>
        ))}
      </div>

      {/* 审核卡片列表 */}
      <div style={{ display: 'grid', gap: '16px' }}>
        {tasks.length === 0 ? (
          <div className="card" style={{ textAlign: 'center', padding: '60px 20px' }}>
            <div style={{ fontSize: '3rem', marginBottom: '16px' }}>🎉</div>
            <h3 style={{ color: '#666', marginBottom: '8px' }}>
              {filter === 'pending' ? '暂无待审核任务' : '暂无任务'}
            </h3>
            <p style={{ color: '#999' }}>
              {filter === 'pending' ? '所有任务都已审核完成！' : '该筛选条件下没有任务'}
            </p>
          </div>
        ) : (
          tasks.map(task => {
            const priorityInfo = getPriorityLabel(task.priority)
            return (
              <div 
                key={task.id} 
                className="card"
                style={{
                  borderLeft: `4px solid ${priorityInfo.color}`,
                  cursor: task.status === 'pending' ? 'pointer' : 'default',
                  transition: 'all 0.2s',
                  opacity: task.status === 'pending' ? 1 : 0.7
                }}
                onClick={() => task.status === 'pending' && openTaskDetail(task)}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                  <div style={{ flex: 1 }}>
                    {/* 头部信息 */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '12px', flexWrap: 'wrap' }}>
                      <span 
                        className="badge"
                        style={{ 
                          background: priorityInfo.color + '20',
                          color: priorityInfo.color,
                          border: `1px solid ${priorityInfo.color}`
                        }}
                      >
                        {priorityInfo.text}
                      </span>
                      <span className={`badge ${task.is_from_long_think ? 'badge-purple' : 'badge-blue'}`}>
                        {getTaskTypeLabel(task.task_type)}
                        {task.is_from_long_think && ' 🧠'}
                      </span>
                      {task.status === 'pending' && (
                        <span className="badge badge-orange">⏳ 待审核</span>
                      )}
                      {task.status === 'approved' && (
                        <span className="badge badge-green">✅ 已批准</span>
                      )}
                      {task.status === 'rejected' && (
                        <span className="badge badge-gray">❌ 已拒绝</span>
                      )}
                    </div>

                    {/* 标题 */}
                    <h4 style={{ margin: '0 0 12px 0', fontSize: '1.1rem' }}>{task.title}</h4>

                    {/* 描述预览 */}
                    <div style={{ 
                      color: '#666', 
                      fontSize: '0.9rem', 
                      lineHeight: '1.6',
                      maxHeight: task.status === 'pending' ? '60px' : 'none',
                      overflow: 'hidden',
                      marginBottom: '12px'
                    }}>
                      {task.description?.substring(0, 200)}
                      {task.description && task.description.length > 200 && task.status === 'pending' && '...'}
                    </div>

                    {/* 底部信息 */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: '16px', fontSize: '0.85rem', color: '#999' }}>
                      <span>📅 {new Date(task.created_at).toLocaleString('zh-CN')}</span>
                      <span>📍 {task.source || '系统'}</span>
                      {task.reviewer && <span>👤 审核人: {task.reviewer}</span>}
                    </div>

                    {/* 审核备注 */}
                    {task.notes && (
                      <div style={{ 
                        marginTop: '12px', 
                        padding: '12px', 
                        background: '#f5f5f5', 
                        borderRadius: '6px',
                        fontSize: '0.85rem',
                        color: '#666'
                      }}>
                        <strong>审核备注:</strong> {task.notes}
                      </div>
                    )}
                  </div>

                  {/* 操作按钮 */}
                  {task.status === 'pending' && (
                    <div style={{ display: 'flex', gap: '8px', marginLeft: '16px' }}>
                      <button 
                        className="btn btn-success" 
                        onClick={(e) => {
                          e.stopPropagation()
                          openTaskDetail(task)
                        }}
                      >
                        审核
                      </button>
                    </div>
                  )}
                </div>
              </div>
            )
          })
        )}
      </div>

      {/* 详情/审核弹窗 */}
      {showDetailModal && selectedTask && (
        <div 
          className="modal-overlay"
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000,
            padding: '20px'
          }}
          onClick={() => setShowDetailModal(false)}
        >
          <div 
            className="modal"
            style={{
              background: 'white',
              borderRadius: '12px',
              padding: '24px',
              maxWidth: '700px',
              width: '100%',
              maxHeight: '90vh',
              overflow: 'auto'
            }}
            onClick={e => e.stopPropagation()}
          >
            {/* 弹窗头部 */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <h3 style={{ margin: 0 }}>🔍 任务审核</h3>
              <button 
                className="btn btn-secondary"
                onClick={() => setShowDetailModal(false)}
              >
                ✕
              </button>
            </div>

            {/* 优先级和类型 */}
            <div style={{ display: 'flex', gap: '12px', marginBottom: '20px', flexWrap: 'wrap' }}>
              {(() => {
                const info = getPriorityLabel(selectedTask.priority)
                return (
                  <span 
                    className="badge"
                    style={{ 
                      background: info.color + '20',
                      color: info.color,
                      border: `1px solid ${info.color}`,
                      fontSize: '1rem',
                      padding: '8px 16px'
                    }}
                  >
                    {info.text}
                  </span>
                )
              })()}
              <span className="badge badge-blue" style={{ fontSize: '1rem', padding: '8px 16px' }}>
                {getTaskTypeLabel(selectedTask.task_type)}
              </span>
            </div>

            {/* 任务标题 */}
            <div style={{ marginBottom: '20px' }}>
              <label style={{ fontSize: '0.85rem', color: '#999', marginBottom: '8px', display: 'block' }}>
                任务标题
              </label>
              <h4 style={{ margin: 0, fontSize: '1.2rem' }}>{selectedTask.title}</h4>
            </div>

            {/* 任务描述 */}
            <div style={{ marginBottom: '20px' }}>
              <label style={{ fontSize: '0.85rem', color: '#999', marginBottom: '8px', display: 'block' }}>
                任务描述
              </label>
              <div style={{ 
                padding: '16px', 
                background: '#f8f9fa', 
                borderRadius: '8px',
                lineHeight: '1.8',
                whiteSpace: 'pre-wrap',
                maxHeight: '300px',
                overflow: 'auto'
              }}>
                {selectedTask.description}
              </div>
            </div>

            {/* 来源和时间 */}
            <div style={{ 
              display: 'grid', 
              gridTemplateColumns: '1fr 1fr', 
              gap: '16px',
              marginBottom: '20px',
              padding: '16px',
              background: '#f0f4ff',
              borderRadius: '8px'
            }}>
              <div>
                <div style={{ fontSize: '0.85rem', color: '#666', marginBottom: '4px' }}>来源</div>
                <div style={{ fontWeight: 600 }}>{selectedTask.source || '系统'}</div>
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', color: '#666', marginBottom: '4px' }}>创建时间</div>
                <div style={{ fontWeight: 600 }}>{new Date(selectedTask.created_at).toLocaleString('zh-CN')}</div>
              </div>
            </div>

            {/* 审核备注输入 */}
            <div style={{ marginBottom: '20px' }}>
              <label style={{ fontSize: '0.85rem', color: '#999', marginBottom: '8px', display: 'block' }}>
                审核备注 (可选)
              </label>
              <textarea
                value={auditNotes}
                onChange={(e) => setAuditNotes(e.target.value)}
                placeholder="输入审核意见或备注..."
                style={{
                  width: '100%',
                  padding: '12px',
                  border: '1px solid #ddd',
                  borderRadius: '8px',
                  minHeight: '100px',
                  fontFamily: 'inherit',
                  fontSize: '0.95rem'
                }}
              />
            </div>

            {/* 操作按钮 */}
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
              <button 
                className="btn btn-secondary"
                onClick={() => setShowDetailModal(false)}
              >
                取消
              </button>
              <button 
                className="btn btn-danger"
                onClick={() => handleReject(selectedTask.id)}
              >
                ❌ 拒绝任务
              </button>
              <button 
                className="btn btn-success"
                onClick={() => handleApprove(selectedTask.id)}
              >
                ✅ 批准执行
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
