import { useState, useEffect } from 'react'
import { 
  User, Mail, Phone, MapPin, Briefcase, GraduationCap, Award, 
  Edit2, Save, X, Plus, Trash2, FileText, CheckCircle2, AlertCircle, Loader2
} from 'lucide-react'

// Types
interface Person {
  id: number
  name: string
  title: string
  email: string
  phone: string
  location: string
  bio: string
  avatar?: string
  tabs: PersonTab[]
  created_at: string
}

interface PersonTab {
  tab_key: string
  tab_label: string
  tab_icon: string
  sort_order: number
  is_custom: number
  is_system: number
  data?: any
}

// Icon mapping
const iconMap: Record<string, React.ComponentType<{size?: number, color?: string}>> = {
  User, Mail, Phone, MapPin, Briefcase, GraduationCap, Award, 
  FileText, Plus, Edit2, Trash2, Save, X
}

const getIcon = (iconName: string) => iconMap[iconName] || FileText

// API Functions
const API_BASE = '/api'

async function fetchPersons(): Promise<Person[]> {
  const res = await fetch(`${API_BASE}/persons`)
  const data = await res.json()
  return data.success ? data.persons : []
}

async function fetchPersonDetail(personId: number): Promise<Person | null> {
  const res = await fetch(`${API_BASE}/persons/${personId}`)
  const data = await res.json()
  return data.success ? data.person : null
}

async function createPerson(personData: Partial<Person>): Promise<number | null> {
  const res = await fetch(`${API_BASE}/persons`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(personData)
  })
  const data = await res.json()
  return data.success ? data.person_id : null
}

async function updatePerson(personId: number, personData: Partial<Person>): Promise<boolean> {
  const res = await fetch(`${API_BASE}/persons/${personId}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(personData)
  })
  const data = await res.json()
  return data.success
}

async function deletePerson(personId: number): Promise<boolean> {
  const res = await fetch(`${API_BASE}/persons/${personId}`, { method: 'DELETE' })
  const data = await res.json()
  return data.success
}

async function addPersonTab(personId: number, tabData: {tab_key: string, tab_label: string, tab_icon: string}): Promise<boolean> {
  const res = await fetch(`${API_BASE}/persons/${personId}/tabs`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(tabData)
  })
  const data = await res.json()
  return data.success
}

async function deletePersonTab(personId: number, tabKey: string): Promise<boolean> {
  const res = await fetch(`${API_BASE}/persons/${personId}/tabs/${tabKey}`, { method: 'DELETE' })
  const data = await res.json()
  return data.success
}

async function updatePersonTabData(personId: number, tabKey: string, data: any): Promise<boolean> {
  const res = await fetch(`${API_BASE}/persons/${personId}/tabs/${tabKey}/data`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data)
  })
  const result = await res.json()
  return result.success
}

// Button Component
const Button = ({ children, variant = 'primary', size = 'md', onClick, disabled = false }: any) => {
  const variants = {
    primary: { bg: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', color: 'white', border: 'none' },
    secondary: { bg: '#e9ecef', color: '#495057', border: 'none' },
    danger: { bg: '#dc3545', color: 'white', border: 'none' },
    ghost: { bg: 'transparent', color: '#667eea', border: '1px solid #667eea' }
  }
  const sizes = { sm: { padding: '6px 12px', fontSize: '12px' }, md: { padding: '10px 20px', fontSize: '14px' } }
  const v = variants[variant as keyof typeof variants]
  const s = sizes[size as keyof typeof sizes]
  return (
    <button onClick={onClick} disabled={disabled} style={{
      background: v.bg, color: v.color, border: v.border, padding: s.padding, fontSize: s.fontSize,
      borderRadius: '8px', cursor: disabled ? 'not-allowed' : 'pointer', fontWeight: 500,
      opacity: disabled ? 0.6 : 1, display: 'inline-flex', alignItems: 'center', gap: '8px'
    }}>{children}</button>
  )
}

// Main Component
export function PersonalInfo() {
  const [persons, setPersons] = useState<Person[]>([])
  const [currentPerson, setCurrentPerson] = useState<Person | null>(null)
  const [activeTab, setActiveTab] = useState<string>('basic')
  const [loading, setLoading] = useState(true)
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null)
  const [showAddModal, setShowAddModal] = useState(false)
  const [newPerson, setNewPerson] = useState({ name: '', title: '', email: '' })

  useEffect(() => { loadPersons() }, [])

  const loadPersons = async () => {
    setLoading(true)
    try {
      const data = await fetchPersons()
      setPersons(data)
      if (data.length > 0 && !currentPerson) loadPersonDetail(data[0].id)
    } catch (error) {
      showToast('加载失败', 'error')
    } finally {
      setLoading(false)
    }
  }

  const loadPersonDetail = async (personId: number) => {
    const data = await fetchPersonDetail(personId)
    if (data) {
      setCurrentPerson(data)
      setActiveTab(data.tabs?.[0]?.tab_key || 'basic')
    }
  }

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type })
    setTimeout(() => setToast(null), 3000)
  }

  const handleCreate = async () => {
    if (!newPerson.name.trim()) { showToast('姓名不能为空', 'error'); return }
    const personId = await createPerson(newPerson)
    if (personId) {
      showToast('创建成功')
      setShowAddModal(false)
      setNewPerson({ name: '', title: '', email: '' })
      loadPersons()
    } else {
      showToast('创建失败', 'error')
    }
  }

  if (loading && !currentPerson) {
    return <div className="page-container"><div style={{ display: 'flex', justifyContent: 'center', padding: '100px' }}><Loader2 size={48} color="#667eea" /></div></div>
  }

  return (
    <div className="page-container">
      {toast && (
        <div style={{ position: 'fixed', top: '80px', right: '24px', background: toast.type === 'success' ? '#28a745' : '#dc3545', 
          color: 'white', padding: '12px 20px', borderRadius: '8px', zIndex: 3000, display: 'flex', alignItems: 'center', gap: '8px' }}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          {toast.message}
        </div>
      )}

      <div className="page-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          <h2 className="page-title">👤 个人信息管理</h2>
          {persons.length > 0 && (
            <select value={currentPerson?.id || ''} onChange={(e) => loadPersonDetail(Number(e.target.value))}
              style={{ padding: '10px 16px', border: '1px solid #ddd', borderRadius: '8px', fontSize: '14px' }}>
              {persons.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          )}
        </div>
        <Button onClick={() => setShowAddModal(true)}><Plus size={18} />添加人员</Button>
      </div>

      {currentPerson && (
        <>
          {/* Tabs */}
          <div style={{ display: 'flex', gap: '8px', marginBottom: '24px', borderBottom: '2px solid #e9ecef', paddingBottom: '12px', flexWrap: 'wrap' }}>
            {currentPerson.tabs?.map((tab) => {
              const Icon = getIcon(tab.tab_icon)
              return (
                <button key={tab.tab_key} onClick={() => setActiveTab(tab.tab_key)} style={{
                  padding: '10px 20px', background: activeTab === tab.tab_key ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' : 'transparent',
                  color: activeTab === tab.tab_key ? 'white' : '#666', border: 'none', borderRadius: '8px', cursor: 'pointer',
                  display: 'flex', alignItems: 'center', gap: '8px'
                }}>
                  <Icon size={16} />{tab.tab_label}
                </button>
              )
            })}
            <button onClick={() => setShowAddModal(true)} style={{
              padding: '10px 16px', background: '#f0f0f0', border: 'none', borderRadius: '8px', cursor: 'pointer'
            }}><Plus size={16} /></button>
          </div>

          {/* Tab Content */}
          <div className="card" style={{ maxWidth: '800px' }}>
            {activeTab === 'basic' && (
              <div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '24px', marginBottom: '24px' }}>
                  <div style={{ width: '100px', height: '100px', borderRadius: '50%', 
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontSize: '2rem' }}>
                    {currentPerson.name?.[0] || '?'}
                  </div>
                  <div>
                    <h2 style={{ margin: 0, marginBottom: '8px' }}>{currentPerson.name}</h2>
                    <p style={{ color: '#666', margin: 0 }}>{currentPerson.title}</p>
                  </div>
                </div>
                <div style={{ display: 'grid', gap: '16px' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <Mail size={20} color="#667eea" /><span>{currentPerson.email || '-'}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <Phone size={20} color="#667eea" /><span>{currentPerson.phone || '-'}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <MapPin size={20} color="#667eea" /><span>{currentPerson.location || '-'}</span>
                  </div>
                  <div>
                    <h4 style={{ marginBottom: '8px' }}>个人简介</h4>
                    <p style={{ color: '#666', lineHeight: 1.6 }}>{currentPerson.bio || '暂无简介'}</p>
                  </div>
                </div>
              </div>
            )}
            {activeTab !== 'basic' && (
              <div>
                <h3>{currentPerson.tabs?.find(t => t.tab_key === activeTab)?.tab_label}</h3>
                <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>
                  Tab内容开发中...<br/>
                  Tab Key: {activeTab}
                </p>
              </div>
            )}
          </div>
        </>
      )}

      {/* Add Person Modal */}
      {showAddModal && (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.5)',
          display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}
          onClick={() => setShowAddModal(false)}>
          <div style={{ background: 'white', padding: '24px', borderRadius: '12px', width: '90%', maxWidth: '400px' }}
            onClick={(e) => e.stopPropagation()}>
            <h3 style={{ margin: '0 0 20px 0' }}>添加人员</h3>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>姓名 *</label>
              <input type="text" value={newPerson.name} onChange={(e) => setNewPerson({...newPerson, name: e.target.value})}
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} />
            </div>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>职位</label>
              <input type="text" value={newPerson.title} onChange={(e) => setNewPerson({...newPerson, title: e.target.value})}
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} />
            </div>
            <div style={{ marginBottom: '24px' }}>
              <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>邮箱</label>
              <input type="email" value={newPerson.email} onChange={(e) => setNewPerson({...newPerson, email: e.target.value})}
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} />
            </div>
            <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
              <Button variant="secondary" onClick={() => setShowAddModal(false)}>取消</Button>
              <Button onClick={handleCreate}><Save size={16} />保存</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
