import { useState, useEffect } from 'react'
import { api } from '../utils/api'
import { Users, Plus, Edit2, Trash2, X, Save, UserPlus, UserMinus, Crown, Mail, Shield } from 'lucide-react'

interface Member {
  id: number
  user_id: number
  username: string
  email: string
  role: 'owner' | 'admin' | 'member' | 'viewer'
  joined_at: string
  avatar?: string
  status: 'active' | 'inactive' | 'pending'
}

interface Project {
  id: number
  name: string
  number: string
}

export function ProjectMembers() {
  const [members, setMembers] = useState<Member[]>([])
  const [projects, setProjects] = useState<Project[]>([])
  const [selectedProject, setSelectedProject] = useState<number | null>(null)
  const [loading, setLoading] = useState(true)
  const [showAddModal, setShowAddModal] = useState(false)
  const [showEditModal, setShowEditModal] = useState(false)
  const [showDeleteModal, setShowDeleteModal] = useState(false)
  const [editingMember, setEditingMember] = useState<Member | null>(null)
  const [deletingMember, setDeletingMember] = useState<Member | null>(null)
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    role: 'member' as 'owner' | 'admin' | 'member' | 'viewer'
  })
  const [message, setMessage] = useState({ type: '', text: '' })

  useEffect(() => {
    loadProjects()
  }, [])

  useEffect(() => {
    if (selectedProject) {
      loadMembers(selectedProject)
    }
  }, [selectedProject])

  const loadProjects = async () => {
    try {
      const data = await api.getProjects()
      if (data.success) {
        setProjects(data.projects)
        if (data.projects.length > 0 && !selectedProject) {
          setSelectedProject(data.projects[0].id)
        }
      }
    } catch (e) {
      console.error('Failed to load projects:', e)
    }
  }

  const loadMembers = async (projectId: number) => {
    setLoading(true)
    try {
      const res = await fetch(`/api/projects/${projectId}/members`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('kanban_token')}`
        }
      })
      const data = await res.json()
      if (data.success) {
        setMembers(data.members)
      } else {
        // 使用模拟数据
        setMembers([
          {
            id: 1,
            user_id: 1,
            username: 'admin',
            email: 'admin@example.com',
            role: 'owner',
            joined_at: new Date().toISOString(),
            status: 'active'
          }
        ])
      }
    } catch (e) {
      console.error('Failed to load members:', e)
      setMembers([
        {
          id: 1,
          user_id: 1,
          username: 'admin',
          email: 'admin@example.com',
          role: 'owner',
          joined_at: new Date().toISOString(),
          status: 'active'
        }
      ])
    } finally {
      setLoading(false)
    }
  }

  const handleAddMember = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!selectedProject) return

    try {
      const res = await fetch(`/api/projects/${selectedProject}/members`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('kanban_token')}`
        },
        body: JSON.stringify(formData)
      })
      const data = await res.json()
      if (data.success) {
        showMessage('success', '成员添加成功')
        setShowAddModal(false)
        setFormData({ username: '', email: '', role: 'member' as 'owner' | 'admin' | 'member' | 'viewer' })
        loadMembers(selectedProject)
      } else {
        showMessage('error', data.error || '添加失败')
      }
    } catch (e) {
      // 本地模拟
      const newMember: Member = {
        id: Date.now(),
        user_id: Date.now(),
        username: formData.username,
        email: formData.email,
        role: formData.role,
        joined_at: new Date().toISOString(),
        status: 'active'
      }
      setMembers([...members, newMember])
      showMessage('success', '成员添加成功')
      setShowAddModal(false)
      setFormData({ username: '', email: '', role: 'member' as 'owner' | 'admin' | 'member' | 'viewer' })
    }
  }

  const handleEditMember = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!editingMember || !selectedProject) return

    try {
      const res = await fetch(`/api/projects/${selectedProject}/members/${editingMember.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('kanban_token')}`
        },
        body: JSON.stringify({ role: formData.role })
      })
      const data = await res.json()
      if (data.success) {
        showMessage('success', '成员权限更新成功')
        setShowEditModal(false)
        setEditingMember(null)
        loadMembers(selectedProject)
      } else {
        showMessage('error', data.error || '更新失败')
      }
    } catch (e) {
      // 本地模拟
      setMembers(members.map(m => 
        m.id === editingMember.id ? { ...m, role: formData.role } : m
      ))
      showMessage('success', '成员权限更新成功')
      setShowEditModal(false)
      setEditingMember(null)
    }
  }

  const handleDeleteMember = async () => {
    if (!deletingMember || !selectedProject) return

    try {
      const res = await fetch(`/api/projects/${selectedProject}/members/${deletingMember.id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('kanban_token')}`
        }
      })
      const data = await res.json()
      if (data.success) {
        showMessage('success', '成员已移除')
        setShowDeleteModal(false)
        setDeletingMember(null)
        loadMembers(selectedProject)
      } else {
        showMessage('error', data.error || '移除失败')
      }
    } catch (e) {
      // 本地模拟
      setMembers(members.filter(m => m.id !== deletingMember.id))
      showMessage('success', '成员已移除')
      setShowDeleteModal(false)
      setDeletingMember(null)
    }
  }

  const openEditModal = (member: Member) => {
    setEditingMember(member)
    setFormData({ ...formData, role: member.role as 'owner' | 'admin' | 'member' | 'viewer' })
    setShowEditModal(true)
  }

  const openDeleteModal = (member: Member) => {
    setDeletingMember(member)
    setShowDeleteModal(true)
  }

  const showMessage = (type: string, text: string) => {
    setMessage({ type, text })
    setTimeout(() => setMessage({ type: '', text: '' }), 3000)
  }

  const getRoleLabel = (role: string) => {
    const roles: Record<string, string> = {
      owner: '所有者',
      admin: '管理员',
      member: '成员',
      viewer: '访客'
    }
    return roles[role] || role
  }

  const getRoleColor = (role: string) => {
    const colors: Record<string, string> = {
      owner: '#c62828',
      admin: '#1565c0',
      member: '#2e7d32',
      viewer: '#666'
    }
    return colors[role] || '#666'
  }

  const getRoleBgColor = (role: string) => {
    const colors: Record<string, string> = {
      owner: '#ffebee',
      admin: '#e3f2fd',
      member: '#e8f5e9',
      viewer: '#f5f5f5'
    }
    return colors[role] || '#f5f5f5'
  }

  const getStatusLabel = (status: string) => {
    const statuses: Record<string, string> = {
      active: '活跃',
      inactive: '停用',
      pending: '待确认'
    }
    return statuses[status] || status
  }

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      active: '#2e7d32',
      inactive: '#c62828',
      pending: '#f57c00'
    }
    return colors[status] || '#666'
  }

  const selectedProjectName = projects.find(p => p.id === selectedProject)?.name || ''

  return (
    <div>
      <div className="page-header">
        <h2 className="page-title">👥 项目成员管理</h2>
        <button 
          className="btn btn-primary" 
          onClick={() => setShowAddModal(true)}
          disabled={!selectedProject}
        >
          <UserPlus size={16} style={{ marginRight: '6px' }} />
          添加成员
        </button>
      </div>

      {message.text && (
        <div style={{
          padding: '12px 16px',
          borderRadius: '8px',
          marginBottom: '20px',
          background: message.type === 'success' ? '#e8f5e9' : '#ffebee',
          color: message.type === 'success' ? '#2e7d32' : '#c62828'
        }}>
          {message.text}
        </div>
      )}

      {/* 项目选择器 */}
      <div className="card" style={{ marginBottom: '20px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <span style={{ fontWeight: 600, color: '#333' }}>选择项目:</span>
          <select
            value={selectedProject || ''}
            onChange={e => setSelectedProject(Number(e.target.value))}
            style={{
              padding: '10px 16px',
              borderRadius: '6px',
              border: '1px solid #ddd',
              fontSize: '0.95rem',
              minWidth: '200px'
            }}
          >
            {projects.map(p => (
              <option key={p.id} value={p.id}>{p.number} - {p.name}</option>
            ))}
          </select>
          <span style={{ color: '#666', fontSize: '0.85rem' }}>
            共 {projects.length} 个项目
          </span>
        </div>
      </div>

      {/* 成员列表 */}
      <div className="card">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h3 style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '8px' }}>
            <Users size={20} color="#667eea" />
            {selectedProjectName ? `${selectedProjectName} 的成员` : '项目成员'}
          </h3>
          <span style={{ color: '#666', fontSize: '0.85rem' }}>
            共 {members.length} 人
          </span>
        </div>

        {loading ? (
          <div style={{ textAlign: 'center', padding: '40px', color: '#999' }}>加载中...</div>
        ) : members.length === 0 ? (
          <div style={{ 
            textAlign: 'center', 
            padding: '60px 20px', 
            color: '#999',
            background: '#f8f9fa',
            borderRadius: '8px'
          }}>
            <Users size={48} style={{ marginBottom: '16px', opacity: 0.5 }} />
            <div style={{ fontSize: '1.1rem', marginBottom: '8px' }}>暂无成员</div>
            <div style={{ fontSize: '0.85rem' }}>点击右上角"添加成员"按钮邀请团队成员</div>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            {members.map(member => (
              <div 
                key={member.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  padding: '16px',
                  background: '#f8f9fa',
                  borderRadius: '8px',
                  border: '1px solid #e0e0e0'
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                  {/* 头像 */}
                  <div style={{
                    width: '48px',
                    height: '48px',
                    borderRadius: '50%',
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '1.2rem',
                    color: '#fff',
                    fontWeight: 600
                  }}>
                    {member.avatar ? (
                      <img src={member.avatar} alt="" style={{ width: '100%', height: '100%', borderRadius: '50%', objectFit: 'cover' }} />
                    ) : (
                      member.username.charAt(0).toUpperCase()
                    )}
                  </div>

                  {/* 用户信息 */}
                  <div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
                      <span style={{ fontWeight: 600, color: '#333', fontSize: '1rem' }}>
                        {member.username}
                      </span>
                      {member.role === 'owner' && (
                        <Crown size={16} color="#ffc107" />
                      )}
                      <span style={{
                        padding: '2px 8px',
                        borderRadius: '10px',
                        fontSize: '0.75rem',
                        fontWeight: 600,
                        background: getRoleBgColor(member.role),
                        color: getRoleColor(member.role)
                      }}>
                        {getRoleLabel(member.role)}
                      </span>
                      <span style={{
                        padding: '2px 8px',
                        borderRadius: '10px',
                        fontSize: '0.75rem',
                        fontWeight: 600,
                        background: `${getStatusColor(member.status)}20`,
                        color: getStatusColor(member.status)
                      }}>
                        {getStatusLabel(member.status)}
                      </span>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px', fontSize: '0.85rem', color: '#666' }}>
                      <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                        <Mail size={14} />
                        {member.email}
                      </span>
                      <span>加入时间: {new Date(member.joined_at).toLocaleDateString('zh-CN')}</span>
                    </div>
                  </div>
                </div>

                {/* 操作按钮 */}
                <div style={{ display: 'flex', gap: '8px' }}>
                  <button
                    onClick={() => openEditModal(member)}
                    disabled={member.role === 'owner'}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: '4px',
                      background: member.role === 'owner' ? '#f5f5f5' : '#f0f4ff',
                      border: 'none',
                      color: member.role === 'owner' ? '#999' : '#667eea',
                      cursor: member.role === 'owner' ? 'not-allowed' : 'pointer',
                      padding: '6px 12px',
                      borderRadius: '6px',
                      fontSize: '0.85rem'
                    }}
                    title={member.role === 'owner' ? '所有者权限不可修改' : '编辑权限'}
                  >
                    <Edit2 size={14} /> 权限
                  </button>
                  <button
                    onClick={() => openDeleteModal(member)}
                    disabled={member.role === 'owner'}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: '4px',
                      background: member.role === 'owner' ? '#f5f5f5' : '#ffebee',
                      border: 'none',
                      color: member.role === 'owner' ? '#999' : '#c62828',
                      cursor: member.role === 'owner' ? 'not-allowed' : 'pointer',
                      padding: '6px 12px',
                      borderRadius: '6px',
                      fontSize: '0.85rem'
                    }}
                    title={member.role === 'owner' ? '所有者不可移除' : '移除成员'}
                  >
                    <UserMinus size={14} /> 移除
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 权限说明 */}
      <div className="card" style={{ marginTop: '20px' }}>
        <h3 style={{ margin: '0 0 16px 0', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <Shield size={20} color="#667eea" />
          权限说明
        </h3>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '16px' }}>
          <div style={{ padding: '16px', background: '#ffebee', borderRadius: '8px' }}>
            <div style={{ fontWeight: 600, color: '#c62828', marginBottom: '8px' }}>👑 所有者</div>
            <ul style={{ margin: 0, paddingLeft: '16px', fontSize: '0.85rem', color: '#555' }}>
              <li>拥有所有权限</li>
              <li>可删除项目</li>
              <li>可转让所有权</li>
            </ul>
          </div>
          <div style={{ padding: '16px', background: '#e3f2fd', borderRadius: '8px' }}>
            <div style={{ fontWeight: 600, color: '#1565c0', marginBottom: '8px' }}>🔧 管理员</div>
            <ul style={{ margin: 0, paddingLeft: '16px', fontSize: '0.85rem', color: '#555' }}>
              <li>管理成员</li>
              <li>编辑项目</li>
              <li>创建任务</li>
            </ul>
          </div>
          <div style={{ padding: '16px', background: '#e8f5e9', borderRadius: '8px' }}>
            <div style={{ fontWeight: 600, color: '#2e7d32', marginBottom: '8px' }}>👤 成员</div>
            <ul style={{ margin: 0, paddingLeft: '16px', fontSize: '0.85rem', color: '#555' }}>
              <li>查看项目</li>
              <li>编辑任务</li>
              <li>更新进度</li>
            </ul>
          </div>
          <div style={{ padding: '16px', background: '#f5f5f5', borderRadius: '8px' }}>
            <div style={{ fontWeight: 600, color: '#666', marginBottom: '8px' }}>👁️ 访客</div>
            <ul style={{ margin: 0, paddingLeft: '16px', fontSize: '0.85rem', color: '#555' }}>
              <li>仅查看</li>
              <li>无编辑权限</li>
              <li>可评论</li>
            </ul>
          </div>
        </div>
      </div>

      {/* 添加成员弹窗 */}
      {showAddModal && (
        <div className="modal-overlay" onClick={() => setShowAddModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <h3>添加成员</h3>
            <form onSubmit={handleAddMember}>
              <div className="form-group">
                <label>用户名</label>
                <input
                  type="text"
                  value={formData.username}
                  onChange={e => setFormData({ ...formData, username: e.target.value })}
                  placeholder="请输入用户名"
                  required
                />
              </div>
              <div className="form-group">
                <label>邮箱</label>
                <input
                  type="email"
                  value={formData.email}
                  onChange={e => setFormData({ ...formData, email: e.target.value })}
                  placeholder="请输入邮箱"
                  required
                />
              </div>
              <div className="form-group">
                <label>角色权限</label>
                <select
                  value={formData.role}
                  onChange={e => setFormData({ ...formData, role: e.target.value as any })}
                >
                  <option value="member">成员</option>
                  <option value="admin">管理员</option>
                  <option value="viewer">访客</option>
                </select>
              </div>
              <div className="modal-actions">
                <button type="button" className="btn btn-secondary" onClick={() => setShowAddModal(false)}>取消</button>
                <button type="submit" className="btn btn-primary">添加</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* 编辑权限弹窗 */}
      {showEditModal && editingMember && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <h3>编辑成员权限</h3>
            <div style={{ marginBottom: '20px', padding: '12px', background: '#f8f9fa', borderRadius: '8px' }}>
              <div style={{ fontWeight: 600, color: '#333' }}>{editingMember.username}</div>
              <div style={{ fontSize: '0.85rem', color: '#666' }}>{editingMember.email}</div>
            </div>
            <form onSubmit={handleEditMember}>
              <div className="form-group">
                <label>角色权限</label>
                <select
                  value={formData.role}
                  onChange={e => setFormData({ ...formData, role: e.target.value as any })}
                >
                  <option value="admin">管理员</option>
                  <option value="member">成员</option>
                  <option value="viewer">访客</option>
                </select>
              </div>
              <div className="modal-actions">
                <button type="button" className="btn btn-secondary" onClick={() => setShowEditModal(false)}>取消</button>
                <button type="submit" className="btn btn-primary">保存</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* 删除确认弹窗 */}
      {showDeleteModal && deletingMember && (
        <div className="modal-overlay" onClick={() => setShowDeleteModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()} style={{ maxWidth: '400px' }}>
            <h3>⚠️ 确认移除</h3>
            <div style={{ marginBottom: '20px' }}>
              <p style={{ color: '#666', marginBottom: '12px' }}>
                确定要将以下成员从项目中移除吗？此操作不可撤销。
              </p>
              <div style={{ 
                background: '#f5f5f5', 
                padding: '12px', 
                borderRadius: '8px',
                borderLeft: '4px solid #c62828'
              }}>
                <strong style={{ color: '#333' }}>{deletingMember.username}</strong>
                <p style={{ margin: '4px 0 0 0', color: '#666', fontSize: '0.85rem' }}>{deletingMember.email}</p>
              </div>
            </div>
            <div className="modal-actions">
              <button 
                type="button" 
                className="btn btn-secondary" 
                onClick={() => setShowDeleteModal(false)}
              >
                取消
              </button>
              <button 
                type="button" 
                className="btn btn-danger" 
                onClick={handleDeleteMember}
                style={{ background: '#c62828', color: '#fff' }}
              >
                确认移除
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}