import { useState, useEffect } from 'react'
import { 
  Building2, Users, FileText, Camera, Edit2, Save, X, Plus, Trash2, 
  CheckCircle2, AlertCircle, Loader2
} from 'lucide-react'

// Types
interface Company {
  id: number
  name: string
  short_name: string
  description: string
  industry: string
  address: string
  logo?: string
  employee_count: number
  tabs: CompanyTab[]
  created_at: string
}

interface CompanyTab {
  tab_key: string
  tab_label: string
  tab_icon: string
  sort_order: number
  is_custom: number
  is_system: number
  data?: any
}

// Icon mapping
const iconMap: Record<string, React.ComponentType<{size?: number, color?: string}>> = {
  Building2, Users, FileText, Camera, Plus, Edit2, Trash2, Save, X
}

const getIcon = (iconName: string) => iconMap[iconName] || FileText

// API Functions
const API_BASE = '/api'

async function fetchCompanies(): Promise<Company[]> {
  const res = await fetch(`${API_BASE}/companies`)
  const data = await res.json()
  return data.success ? data.companies : []
}

async function fetchCompanyDetail(companyId: number): Promise<Company | null> {
  const res = await fetch(`${API_BASE}/companies/${companyId}`)
  const data = await res.json()
  return data.success ? data.company : null
}

async function createCompany(companyData: Partial<Company>): Promise<number | null> {
  const res = await fetch(`${API_BASE}/companies`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(companyData)
  })
  const data = await res.json()
  return data.success ? data.company_id : null
}

async function deleteCompany(companyId: number): Promise<boolean> {
  const res = await fetch(`${API_BASE}/companies/${companyId}`, { method: 'DELETE' })
  const data = await res.json()
  return data.success
}

async function addCompanyTab(companyId: number, tabData: {tab_key: string, tab_label: string, tab_icon: string}): Promise<boolean> {
  const res = await fetch(`${API_BASE}/companies/${companyId}/tabs`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(tabData)
  })
  const data = await res.json()
  return data.success
}

async function deleteCompanyTab(companyId: number, tabKey: string): Promise<boolean> {
  const res = await fetch(`${API_BASE}/companies/${companyId}/tabs/${tabKey}`, { method: 'DELETE' })
  const data = await res.json()
  return data.success
}

// Button Component
const Button = ({ children, variant = 'primary', size = 'md', onClick, disabled = false }: any) => {
  const variants = {
    primary: { bg: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', color: 'white', border: 'none' },
    secondary: { bg: '#e9ecef', color: '#495057', border: 'none' },
    danger: { bg: '#dc3545', color: 'white', border: 'none' },
    ghost: { bg: 'transparent', color: '#667eea', border: '1px solid #667eea' }
  }
  const sizes = { sm: { padding: '6px 12px', fontSize: '12px' }, md: { padding: '10px 20px', fontSize: '14px' } }
  const v = variants[variant as keyof typeof variants]
  const s = sizes[size as keyof typeof sizes]
  return (
    <button onClick={onClick} disabled={disabled} style={{
      background: v.bg, color: v.color, border: v.border, padding: s.padding, fontSize: s.fontSize,
      borderRadius: '8px', cursor: disabled ? 'not-allowed' : 'pointer', fontWeight: 500,
      opacity: disabled ? 0.6 : 1, display: 'inline-flex', alignItems: 'center', gap: '8px'
    }}>{children}</button>
  )
}

// Main Component
export function CompanyInfo() {
  const [companies, setCompanies] = useState<Company[]>([])
  const [currentCompany, setCurrentCompany] = useState<Company | null>(null)
  const [activeTab, setActiveTab] = useState<string>('basic')
  const [loading, setLoading] = useState(true)
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null)
  const [showAddModal, setShowAddModal] = useState(false)
  const [newCompany, setNewCompany] = useState({ name: '', short_name: '', industry: '' })

  useEffect(() => { loadCompanies() }, [])

  const loadCompanies = async () => {
    setLoading(true)
    try {
      const data = await fetchCompanies()
      setCompanies(data)
      if (data.length > 0 && !currentCompany) loadCompanyDetail(data[0].id)
    } catch (error) {
      showToast('加载失败', 'error')
    } finally {
      setLoading(false)
    }
  }

  const loadCompanyDetail = async (companyId: number) => {
    const data = await fetchCompanyDetail(companyId)
    if (data) {
      setCurrentCompany(data)
      setActiveTab(data.tabs?.[0]?.tab_key || 'basic')
    }
  }

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type })
    setTimeout(() => setToast(null), 3000)
  }

  const handleCreate = async () => {
    if (!newCompany.name.trim()) { showToast('公司名称不能为空', 'error'); return }
    const companyId = await createCompany(newCompany)
    if (companyId) {
      showToast('创建成功')
      setShowAddModal(false)
      setNewCompany({ name: '', short_name: '', industry: '' })
      loadCompanies()
    } else {
      showToast('创建失败', 'error')
    }
  }

  if (loading && !currentCompany) {
    return <div className="page-container"><div style={{ display: 'flex', justifyContent: 'center', padding: '100px' }}><Loader2 size={48} color="#667eea" /></div></div>
  }

  return (
    <div className="page-container">
      {toast && (
        <div style={{ position: 'fixed', top: '80px', right: '24px', background: toast.type === 'success' ? '#28a745' : '#dc3545', 
          color: 'white', padding: '12px 20px', borderRadius: '8px', zIndex: 3000, display: 'flex', alignItems: 'center', gap: '8px' }}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          {toast.message}
        </div>
      )}

      <div className="page-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          <h2 className="page-title">🏢 公司信息管理</h2>
          {companies.length > 0 && (
            <select value={currentCompany?.id || ''} onChange={(e) => loadCompanyDetail(Number(e.target.value))}
              style={{ padding: '10px 16px', border: '1px solid #ddd', borderRadius: '8px', fontSize: '14px' }}>
              {companies.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          )}
        </div>
        <Button onClick={() => setShowAddModal(true)}><Plus size={18} />添加公司</Button>
      </div>

      {currentCompany && (
        <>
          {/* Tabs */}
          <div style={{ display: 'flex', gap: '8px', marginBottom: '24px', borderBottom: '2px solid #e9ecef', paddingBottom: '12px', flexWrap: 'wrap' }}>
            {currentCompany.tabs?.map((tab) => {
              const Icon = getIcon(tab.tab_icon)
              return (
                <button key={tab.tab_key} onClick={() => setActiveTab(tab.tab_key)} style={{
                  padding: '10px 20px', background: activeTab === tab.tab_key ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' : 'transparent',
                  color: activeTab === tab.tab_key ? 'white' : '#666', border: 'none', borderRadius: '8px', cursor: 'pointer',
                  display: 'flex', alignItems: 'center', gap: '8px'
                }}>
                  <Icon size={16} />{tab.tab_label}
                </button>
              )
            })}
            <button onClick={() => setShowAddModal(true)} style={{
              padding: '10px 16px', background: '#f0f0f0', border: 'none', borderRadius: '8px', cursor: 'pointer'
            }}><Plus size={16} /></button>
          </div>

          {/* Tab Content */}
          <div className="card" style={{ maxWidth: '800px' }}>
            {activeTab === 'basic' && (
              <div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '24px', marginBottom: '24px' }}>
                  <div style={{ width: '100px', height: '100px', borderRadius: '12px', 
                    background: currentCompany.logo ? `url(${currentCompany.logo}) center/cover` : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white' }}>
                    {!currentCompany.logo && <Building2 size={48} />}
                  </div>
                  <div>
                    <h2 style={{ margin: 0, marginBottom: '8px' }}>{currentCompany.name}</h2>
                    <p style={{ color: '#666', margin: 0 }}>{currentCompany.short_name}</p>
                  </div>
                </div>
                <div style={{ display: 'grid', gap: '16px' }}>
                  <div><strong>行业:</strong> {currentCompany.industry || '-'}</div>
                  <div><strong>地址:</strong> {currentCompany.address || '-'}</div>
                  <div><strong>员工数:</strong> {currentCompany.employee_count || 0} 人</div>
                  <div>
                    <strong>简介:</strong>
                    <p style={{ color: '#666', lineHeight: 1.6, marginTop: '8px' }}>{currentCompany.description || '暂无简介'}</p>
                  </div>
                </div>
              </div>
            )}
            {activeTab !== 'basic' && (
              <div>
                <h3>{currentCompany.tabs?.find(t => t.tab_key === activeTab)?.tab_label}</h3>
                <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>
                  Tab内容开发中...<br/>
                  Tab Key: {activeTab}
                </p>
              </div>
            )}
          </div>
        </>
      )}

      {/* Add Company Modal */}
      {showAddModal && (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.5)',
          display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}
          onClick={() => setShowAddModal(false)}>
          <div style={{ background: 'white', padding: '24px', borderRadius: '12px', width: '90%', maxWidth: '400px' }}
            onClick={(e) => e.stopPropagation()}>
            <h3 style={{ margin: '0 0 20px 0' }}>添加公司</h3>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>公司名称 *</label>
              <input type="text" value={newCompany.name} onChange={(e) => setNewCompany({...newCompany, name: e.target.value})}
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} />
            </div>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>简称</label>
              <input type="text" value={newCompany.short_name} onChange={(e) => setNewCompany({...newCompany, short_name: e.target.value})}
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} />
            </div>
            <div style={{ marginBottom: '24px' }}>
              <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>行业</label>
              <input type="text" value={newCompany.industry} onChange={(e) => setNewCompany({...newCompany, industry: e.target.value})}
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} />
            </div>
            <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
              <Button variant="secondary" onClick={() => setShowAddModal(false)}>取消</Button>
              <Button onClick={handleCreate}><Save size={16} />保存</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
