import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { 
  User, Calendar, Briefcase, Building, FileText, GraduationCap,
  Phone, Mail, Download, ChevronLeft, Folder, Clock, Mic, Quote,
  Sparkles, Building2, Shield, AlertTriangle, CheckCircle2, Scale,
  Award, BookOpen, Lightbulb, Trophy, Loader2, ArrowLeft, Edit2,
  Plus, Trash2, Save, X
} from 'lucide-react'

interface ContractInfo {
  contractNo: string
  position: string
  positionType: string
  department: string
  startDate: string
  endDate: string
  duration: string
  requirements: string[]
  fileName: string
}

interface WorkExperience {
  company: string
  position: string
  department?: string
  startDate: string
  endDate?: string
  type: 'academic' | 'entrepreneurship' | 'industry'
}

interface Award {
  name: string
  year: string
  organization: string
  description?: string
}

interface Paper {
  title: string
  journal: string
  year: string
  role: string
  doi?: string
}

interface Patent {
  title: string
  status: string
  year: string
  applicationNumber?: string
  inventors?: string[]
}

interface EntrepreneurshipInfo {
  company: string
  position: string
  founded: string
  description: string
  focus: string[]
}

interface PublicSpeaking {
  id: string
  title: string
  event: string
  organizer: string
  date: string
  content: string
  keyPoints: string[]
  source: string
}

interface ComplianceInfo {
  title: string
  summary: string
  keyPoints: {
    title: string
    items: string[]
  }[]
  commitments: string[]
  updateDate: string
  documentUrl?: string
}

interface PersonDetail {
  id: number
  name: string
  english_name?: string
  position?: string
  company?: string
  department?: string
  email?: string
  phone?: string
  location?: string
  bio?: string
  expertise?: string[]
  avatar_url?: string
  birthDate?: string
  gender?: string
  education?: { school: string; degree: string; major: string; year: string }[]
  workExperience?: WorkExperience[]
  researchAreas?: string[]
  awards?: Award[]
  papers?: Paper[]
  patents?: Patent[]
  contract?: ContractInfo
  entrepreneurship?: EntrepreneurshipInfo
  publicSpeaking?: PublicSpeaking[]
  compliance?: ComplianceInfo
  tabs: PersonTab[]
  created_at: string
  updated_at: string
}

interface PersonTab {
  id: number
  person_id: number
  tab_key: string
  tab_label: string
  tab_icon: string
  sort_order: number
  is_custom: number
  is_system: number
  data?: any
}

// Icon mapping
const iconMap: Record<string, React.ComponentType<{size?: number, color?: string}>> = {
  User, Calendar, Briefcase, Building, FileText, GraduationCap,
  Phone, Mail, Download, Folder, Clock, Mic, Quote, Sparkles,
  Building2, Shield, AlertTriangle, CheckCircle2, Scale, Award,
  BookOpen, Lightbulb, Trophy, Edit2, Plus, Trash2, Save, X
}

const getIcon = (iconName: string) => iconMap[iconName] || FileText

const API_BASE = '/api'

export function PersonDetail() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const [detail, setDetail] = useState<PersonDetail | null>(null)
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<string>('basic')
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null)

  useEffect(() => {
    if (id) {
      fetchPersonDetail(parseInt(id))
    }
  }, [id])

  const fetchPersonDetail = async (personId: number) => {
    setLoading(true)
    try {
      const res = await fetch(`${API_BASE}/persons/${personId}`)
      const data = await res.json()
      if (data.success) {
        setDetail(data.person)
        if (data.person.tabs && data.person.tabs.length > 0) {
          setActiveTab(data.person.tabs[0].tab_key)
        }
      } else {
        showToast('加载失败', 'error')
      }
    } catch (error) {
      console.error('Error fetching person detail:', error)
      showToast('加载失败', 'error')
    } finally {
      setLoading(false)
    }
  }

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type })
    setTimeout(() => setToast(null), 3000)
  }

  const handleAddTab = async () => {
    const tabKey = prompt('请输入 Tab 标识 (英文，如: meetings):')
    if (!tabKey) return
    
    const tabLabel = prompt('请输入 Tab 显示名称 (如: 参与的会议):')
    if (!tabLabel) return
    
    const tabIcon = prompt('请输入图标名称 (如: Calendar, FileText, Mic):', 'FileText')
    
    try {
      const res = await fetch(`${API_BASE}/persons/${detail?.id}/tabs`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tab_key: tabKey,
          tab_label: tabLabel,
          tab_icon: tabIcon || 'FileText'
        })
      })
      const data = await res.json()
      if (data.success) {
        showToast('添加成功')
        fetchPersonDetail(detail!.id)
      } else {
        showToast(data.message || '添加失败', 'error')
      }
    } catch (error) {
      showToast('添加失败', 'error')
    }
  }

  const handleDeleteTab = async (tabKey: string, isSystem: number) => {
    if (isSystem) {
      showToast('系统 Tab 不能删除', 'error')
      return
    }
    
    if (!confirm('确定要删除这个 Tab 吗？')) return
    
    try {
      const res = await fetch(`${API_BASE}/persons/${detail?.id}/tabs/${tabKey}`, {
        method: 'DELETE'
      })
      const data = await res.json()
      if (data.success) {
        showToast('删除成功')
        fetchPersonDetail(detail!.id)
      } else {
        showToast(data.message || '删除失败', 'error')
      }
    } catch (error) {
      showToast('删除失败', 'error')
    }
  }

  if (loading) {
    return (
      <div className="page-container">
        <div style={{ display: 'flex', justifyContent: 'center', padding: '100px' }}>
          <Loader2 size={48} color="#667eea" className="animate-spin" />
        </div>
      </div>
    )
  }

  if (!detail) {
    return (
      <div className="page-container">
        <div style={{ padding: '40px', textAlign: 'center' }}>
          <h2>人员不存在</h2>
          <button onClick={() => navigate('/persons')} style={{ marginTop: '20px', padding: '10px 20px' }}>
            返回列表
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="page-container">
      {toast && (
        <div style={{ 
          position: 'fixed', top: '80px', right: '24px', 
          background: toast.type === 'success' ? '#28a745' : '#dc3545',
          color: 'white', padding: '12px 20px', borderRadius: '8px', 
          zIndex: 3000, display: 'flex', alignItems: 'center', gap: '8px' 
        }}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
          {toast.message}
        </div>
      )}

      {/* Header */}
      <div className="page-header" style={{ marginBottom: '24px' }}>
        <button 
          onClick={() => navigate('/persons')}
          style={{ 
            display: 'flex', alignItems: 'center', gap: '8px',
            background: 'none', border: 'none', cursor: 'pointer',
            color: '#667eea', fontSize: '14px', marginBottom: '16px'
          }}
        >
          <ArrowLeft size={18} /> 返回列表
        </button>
        <h2 className="page-title">👤 {detail.name}</h2>
        <p style={{ color: '#666', marginTop: '8px' }}>{detail.position || detail.english_name}</p>
      </div>

      {/* Tabs */}
      <div style={{ 
        display: 'flex', gap: '8px', marginBottom: '24px', 
        borderBottom: '2px solid #e9ecef', paddingBottom: '12px',
        flexWrap: 'wrap', alignItems: 'center'
      }}>
        {detail.tabs?.map((tab) => {
          const Icon = getIcon(tab.tab_icon)
          return (
            <div key={tab.id} style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
              <button 
                onClick={() => setActiveTab(tab.tab_key)} 
                style={{
                  padding: '10px 20px', 
                  background: activeTab === tab.tab_key 
                    ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' 
                    : 'transparent',
                  color: activeTab === tab.tab_key ? 'white' : '#666', 
                  border: 'none', borderRadius: '8px', cursor: 'pointer',
                  display: 'flex', alignItems: 'center', gap: '8px'
                }}
              >
                <Icon size={16} />{tab.tab_label}
              </button>
              {!tab.is_system && (
                <button
                  onClick={() => handleDeleteTab(tab.tab_key, tab.is_system)}
                  style={{
                    padding: '4px', background: 'none', border: 'none',
                    cursor: 'pointer', color: '#dc3545'
                  }}
                >
                  <Trash2 size={14} />
                </button>
              )}
            </div>
          )
        })}
        <button 
          onClick={handleAddTab}
          style={{
            padding: '10px 16px', background: '#f0f0f0', 
            border: 'none', borderRadius: '8px', cursor: 'pointer',
            display: 'flex', alignItems: 'center', gap: '4px'
          }}
        >
          <Plus size={16} />
        </button>
      </div>

      {/* Tab Content */}
      <div className="card" style={{ maxWidth: '1000px' }}>
        {activeTab === 'basic' && (
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '24px', marginBottom: '24px' }}>
              <div style={{ 
                width: '100px', height: '100px', borderRadius: '50%', 
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                display: 'flex', alignItems: 'center', justifyContent: 'center', 
                color: 'white', fontSize: '2rem', fontWeight: 'bold'
              }}>
                {detail.name?.[0] || '?'}
              </div>
              <div>
                <h2 style={{ margin: 0, marginBottom: '8px' }}>{detail.name}</h2>
                <p style={{ color: '#666', margin: 0 }}>
                  {detail.position} {detail.company && `@ ${detail.company}`}
                </p>
                {detail.department && <p style={{ color: '#999', margin: '4px 0 0 0' }}>{detail.department}</p>}
              </div>
            </div>

            <div style={{ display: 'grid', gap: '16px', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))' }}>
              {detail.email && (
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                  <Mail size={20} color="#667eea" />
                  <span>{detail.email}</span>
                </div>
              )}
              {detail.phone && (
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                  <Phone size={20} color="#667eea" />
                  <span>{detail.phone}</span>
                </div>
              )}
              {detail.location && (
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                  <User size={20} color="#667eea" />
                  <span>{detail.location}</span>
                </div>
              )}
              {detail.expertise && detail.expertise.length > 0 && (
                <div style={{ gridColumn: '1 / -1' }}>
                  <h4 style={{ marginBottom: '8px' }}>专业领域</h4>
                  <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                    {detail.expertise.map((exp, idx) => (
                      <span key={idx} style={{
                        padding: '4px 12px', background: '#f0f0f0', borderRadius: '16px', fontSize: '13px'
                      }}>{exp}</span>
                    ))}
                  </div>
                </div>
              )}
              {detail.bio && (
                <div style={{ gridColumn: '1 / -1' }}>
                  <h4 style={{ marginBottom: '8px' }}>个人简介</h4>
                  <p style={{ color: '#666', lineHeight: 1.6 }}>{detail.bio}</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Experience Tab */}
        {activeTab === 'experience' && (
          <div>
            <h3 style={{ marginBottom: '20px' }}>工作经历</h3>
            {detail.workExperience && detail.workExperience.length > 0 ? (
              <div style={{ display: 'grid', gap: '16px' }}>
                {detail.workExperience.map((exp, idx) => (
                  <div key={idx} style={{
                    padding: '16px', border: '1px solid #e9ecef', borderRadius: '8px'
                  }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                      <h4 style={{ margin: 0 }}>{exp.position}</h4>
                      <span style={{ color: '#999', fontSize: '14px' }}>
                        {exp.startDate} - {exp.endDate || '至今'}
                      </span>
                    </div>
                    <p style={{ color: '#666', margin: '4px 0' }}>{exp.company}</p>
                    {exp.department && <p style={{ color: '#999', fontSize: '14px' }}>{exp.department}</p>}
                  </div>
                ))}
              </div>
            ) : (
              <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>暂无工作经历</p>
            )}
          </div>
        )}

        {/* Education Tab */}
        {activeTab === 'education' && (
          <div>
            <h3 style={{ marginBottom: '20px' }}>教育背景</h3>
            {detail.education && detail.education.length > 0 ? (
              <div style={{ display: 'grid', gap: '16px' }}>
                {detail.education.map((edu, idx) => (
                  <div key={idx} style={{
                    padding: '16px', border: '1px solid #e9ecef', borderRadius: '8px'
                  }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                      <h4 style={{ margin: 0 }}>{edu.school}</h4>
                      <span style={{ color: '#999', fontSize: '14px' }}>{edu.year}</span>
                    </div>
                    <p style={{ color: '#666', margin: '4px 0' }}>{edu.degree} - {edu.major}</p>
                  </div>
                ))}
              </div>
            ) : (
              <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>暂无教育背景</p>
            )}
          </div>
        )}

        {/* Awards Tab */}
        {activeTab === 'awards' && (
          <div>
            <h3 style={{ marginBottom: '20px' }}>荣誉奖项</h3>
            {detail.awards && detail.awards.length > 0 ? (
              <div style={{ display: 'grid', gap: '16px' }}>
                {detail.awards.map((award, idx) => (
                  <div key={idx} style={{
                    padding: '16px', border: '1px solid #e9ecef', borderRadius: '8px'
                  }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                      <h4 style={{ margin: 0 }}>{award.name}</h4>
                      <span style={{ color: '#999', fontSize: '14px' }}>{award.year}</span>
                    </div>
                    <p style={{ color: '#666', margin: '4px 0' }}>{award.organization}</p>
                    {award.description && <p style={{ color: '#999', fontSize: '14px', marginTop: '8px' }}>{award.description}</p>}
                  </div>
                ))}
              </div>
            ) : (
              <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>暂无荣誉奖项</p>
            )}
          </div>
        )}

        {/* Papers Tab */}
        {activeTab === 'papers' && (
          <div>
            <h3 style={{ marginBottom: '20px' }}>学术论文</h3>
            {detail.papers && detail.papers.length > 0 ? (
              <div style={{ display: 'grid', gap: '16px' }}>
                {detail.papers.map((paper, idx) => (
                  <div key={idx} style={{
                    padding: '16px', border: '1px solid #e9ecef', borderRadius: '8px'
                  }}>
                    <h4 style={{ margin: '0 0 8px 0' }}>{paper.title}</h4>
                    <p style={{ color: '#666', margin: '4px 0' }}>{paper.journal}, {paper.year}</p>
                    <p style={{ color: '#999', fontSize: '14px' }}>角色：{paper.role}</p>
                    {paper.doi && <p style={{ color: '#667eea', fontSize: '13px', marginTop: '8px' }}>DOI: {paper.doi}</p>}
                  </div>
                ))}
              </div>
            ) : (
              <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>暂无学术论文</p>
            )}
          </div>
        )}

        {/* Patents Tab */}
        {activeTab === 'patents' && (
          <div>
            <h3 style={{ marginBottom: '20px' }}>专利</h3>
            {detail.patents && detail.patents.length > 0 ? (
              <div style={{ display: 'grid', gap: '16px' }}>
                {detail.patents.map((patent, idx) => (
                  <div key={idx} style={{
                    padding: '16px', border: '1px solid #e9ecef', borderRadius: '8px'
                  }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                      <h4 style={{ margin: 0 }}>{patent.title}</h4>
                      <span style={{ 
                        padding: '2px 8px', borderRadius: '4px', fontSize: '12px',
                        background: patent.status === '授权' ? '#28a745' : '#ffc107',
                        color: 'white'
                      }}>{patent.status}</span>
                    </div>
                    <p style={{ color: '#999', fontSize: '14px' }}>{patent.year}</p>
                    {patent.applicationNumber && (
                      <p style={{ color: '#666', fontSize: '13px', marginTop: '8px' }}>申请号：{patent.applicationNumber}</p>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>暂无专利</p>
            )}
          </div>
        )}

        {/* Speaking Tab */}
        {activeTab === 'speaking' && (
          <div>
            <h3 style={{ marginBottom: '20px' }}>公开演讲</h3>
            {detail.publicSpeaking && detail.publicSpeaking.length > 0 ? (
              <div style={{ display: 'grid', gap: '16px' }}>
                {detail.publicSpeaking.map((speech, idx) => (
                  <div key={speech.id || idx} style={{
                    padding: '16px', border: '1px solid #e9ecef', borderRadius: '8px'
                  }}>
                    <h4 style={{ margin: '0 0 8px 0' }}>{speech.title}</h4>
                    <p style={{ color: '#666', margin: '4px 0' }}>{speech.event}</p>
                    <p style={{ color: '#999', fontSize: '14px' }}>
                      {speech.organizer} · {speech.date}
                    </p>
                    {speech.keyPoints && speech.keyPoints.length > 0 && (
                      <div style={{ marginTop: '12px' }}>
                        <h5 style={{ margin: '0 0 8px 0', fontSize: '14px' }}>核心观点：</h5>
                        <ul style={{ margin: 0, paddingLeft: '20px', color: '#666' }}>
                          {speech.keyPoints.map((point, i) => (
                            <li key={i} style={{ marginBottom: '4px' }}>{point}</li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>暂无公开演讲</p>
            )}
          </div>
        )}

        {/* Contract Tab */}
        {activeTab === 'contract' && (
          <div>
            <h3 style={{ marginBottom: '20px' }}>合同信息</h3>
            {detail.contract ? (
              <div style={{ padding: '16px', border: '1px solid #e9ecef', borderRadius: '8px' }}>
                <div style={{ display: 'grid', gap: '12px' }}>
                  <div><strong>合同编号：</strong>{detail.contract.contractNo}</div>
                  <div><strong>职位：</strong>{detail.contract.position}</div>
                  <div><strong>岗位类型：</strong>{detail.contract.positionType}</div>
                  <div><strong>部门：</strong>{detail.contract.department}</div>
                  <div><strong>聘期：</strong>{detail.contract.startDate} 至 {detail.contract.endDate}（{detail.contract.duration}）</div>
                  <div>
                    <strong>工作要求：</strong>
                    <ul style={{ marginTop: '8px' }}>
                      {detail.contract.requirements.map((req, idx) => (
                        <li key={idx} style={{ marginBottom: '4px' }}>{req}</li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            ) : (
              <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>暂无合同信息</p>
            )}
          </div>
        )}

        {/* Entrepreneurship Tab */}
        {activeTab === 'entrepreneurship' && (
          <div>
            <h3 style={{ marginBottom: '20px' }}>创业信息</h3>
            {detail.entrepreneurship ? (
              <div style={{ padding: '16px', border: '1px solid #e9ecef', borderRadius: '8px' }}>
                <h4 style={{ margin: '0 0 8px 0' }}>{detail.entrepreneurship.company}</h4>
                <p style={{ color: '#666', margin: '4px 0' }}>{detail.entrepreneurship.position} · 成立于 {detail.entrepreneurship.founded}</p>
                <p style={{ color: '#666', marginTop: '12px', lineHeight: 1.6 }}>{detail.entrepreneurship.description}</p>
                {detail.entrepreneurship.focus && detail.entrepreneurship.focus.length > 0 && (
                  <div style={{ marginTop: '16px' }}>
                    <h5 style={{ margin: '0 0 8px 0' }}>关注领域：</h5>
                    <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                      {detail.entrepreneurship.focus.map((f, idx) => (
                        <span key={idx} style={{
                          padding: '4px 12px', background: '#f0f0f0', borderRadius: '16px', fontSize: '13px'
                        }}>{f}</span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>暂无创业信息</p>
            )}
          </div>
        )}

        {/* Compliance Tab */}
        {activeTab === 'compliance' && (
          <div>
            <h3 style={{ marginBottom: '20px' }}>合规声明</h3>
            {detail.compliance ? (
              <div style={{ padding: '16px', border: '1px solid #e9ecef', borderRadius: '8px' }}>
                <h4 style={{ margin: '0 0 12px 0' }}>{detail.compliance.title}</h4>
                <p style={{ color: '#666', lineHeight: 1.6, marginBottom: '16px' }}>{detail.compliance.summary}</p>
                
                {detail.compliance.keyPoints.map((point, idx) => (
                  <div key={idx} style={{ marginBottom: '16px' }}>
                    <h5 style={{ margin: '0 0 8px 0', color: '#667eea' }}>{point.title}</h5>
                    <ul style={{ margin: 0, paddingLeft: '20px', color: '#666' }}>
                      {point.items.map((item, i) => (
                        <li key={i} style={{ marginBottom: '4px' }}>{item}</li>
                      ))}
                    </ul>
                  </div>
                ))}

                <div style={{ marginTop: '20px', padding: '12px', background: '#f8f9fa', borderRadius: '8px' }}>
                  <h5 style={{ margin: '0 0 8px 0' }}>承诺事项：</h5>
                  <ul style={{ margin: 0, paddingLeft: '20px', color: '#666' }}>
                    {detail.compliance.commitments.map((commitment, idx) => (
                      <li key={idx} style={{ marginBottom: '4px' }}>{commitment}</li>
                    ))}
                  </ul>
                </div>

                <p style={{ color: '#999', fontSize: '13px', marginTop: '16px' }}>
                  更新日期：{detail.compliance.updateDate}
                </p>
              </div>
            ) : (
              <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>暂无合规声明</p>
            )}
          </div>
        )}

        {/* Dynamic Tab Content */}
        {!['basic', 'experience', 'education', 'awards', 'papers', 'patents', 'speaking', 'contract', 'entrepreneurship', 'compliance'].includes(activeTab) && (
          <div>
            <h3>{detail.tabs?.find(t => t.tab_key === activeTab)?.tab_label}</h3>
            <p style={{ color: '#999', padding: '40px 0', textAlign: 'center' }}>
              自定义 Tab 内容开发中...<br/>
              Tab Key: {activeTab}
            </p>
          </div>
        )}
      </div>
    </div>
  )
}
