import { useState, useEffect } from 'react'
import { FileText, Plus, Search, Tag, Calendar, Edit2, Trash2, Save, X, ExternalLink } from 'lucide-react'

interface Note {
  id: string
  title: string
  content: string
  category: string
  tags: string[]
  createdAt: string
  updatedAt: string
}

const defaultNotes: Note[] = [
  {
    id: '1',
    title: 'T109平台架构设计',
    content: 'T109是一个基于AI的过渡态计算平台，主要功能包括...',
    category: '技术方案',
    tags: ['T109', '架构', 'AI'],
    createdAt: '2026-03-01',
    updatedAt: '2026-03-01'
  },
  {
    id: '2',
    title: 'Pepi数字人技术调研',
    content: '调研了LiveTalking、DUIX等开源数字人方案...',
    category: '调研',
    tags: ['Pepi', '数字人', 'LiveTalking'],
    createdAt: '2026-03-05',
    updatedAt: '2026-03-05'
  }
]

const categories = ['全部', '技术方案', '调研', '会议记录', '文献笔记', '其他']

export function ResearchNotes() {
  const [notes, setNotes] = useState<Note[]>(defaultNotes)
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState('全部')
  const [showModal, setShowModal] = useState(false)
  const [editingNote, setEditingNote] = useState<Note | null>(null)
  const [formData, setFormData] = useState<Partial<Note>>({
    title: '',
    content: '',
    category: '调研',
    tags: []
  })
  const [newTag, setNewTag] = useState('')

  const filteredNotes = notes.filter(note => {
    const matchesSearch = !searchQuery ||
      note.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      note.content.toLowerCase().includes(searchQuery.toLowerCase()) ||
      note.tags.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()))
    const matchesCategory = selectedCategory === '全部' || note.category === selectedCategory
    return matchesSearch && matchesCategory
  })

  const allTags = Array.from(new Set(notes.flatMap(n => n.tags)))

  const handleSave = () => {
    if (!formData.title) return

    const now = new Date().toISOString().split('T')[0]
    
    if (editingNote) {
      setNotes(notes.map(n => n.id === editingNote.id ? {
        ...n,
        ...formData,
        updatedAt: now
      } as Note : n))
    } else {
      const newNote: Note = {
        id: Date.now().toString(),
        title: formData.title || '',
        content: formData.content || '',
        category: formData.category || '调研',
        tags: formData.tags || [],
        createdAt: now,
        updatedAt: now
      }
      setNotes([newNote, ...notes])
    }

    setShowModal(false)
    setEditingNote(null)
    setFormData({ title: '', content: '', category: '调研', tags: [] })
  }

  const handleDelete = (id: string) => {
    if (confirm('确定要删除这条笔记吗？')) {
      setNotes(notes.filter(n => n.id !== id))
    }
  }

  const openEdit = (note: Note) => {
    setEditingNote(note)
    setFormData(note)
    setShowModal(true)
  }

  const addTag = () => {
    if (newTag && !formData.tags?.includes(newTag)) {
      setFormData({ ...formData, tags: [...(formData.tags || []), newTag] })
      setNewTag('')
    }
  }

  const removeTag = (tag: string) => {
    setFormData({ ...formData, tags: formData.tags?.filter(t => t !== tag) || [] })
  }

  return (
    <div>
      <div className="page-header">
        <h2 className="page-title">📚 调研笔记</h2>
        <button
          onClick={() => {
            setEditingNote(null)
            setFormData({ title: '', content: '', category: '调研', tags: [] })
            setShowModal(true)
          }}
          style={{
            padding: '10px 20px',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            gap: '8px'
          }}
        >
          <Plus size={18} />
          新建笔记
        </button>
      </div>

      {/* 搜索和筛选 */}
      <div style={{
        display: 'flex',
        gap: '16px',
        marginBottom: '24px',
        flexWrap: 'wrap'
      }}>
        <div style={{ position: 'relative', flex: 1, minWidth: '250px' }}>
          <Search size={18} style={{
            position: 'absolute',
            left: '12px',
            top: '50%',
            transform: 'translateY(-50%)',
            color: '#999'
          }} />
          <input
            type="text"
            placeholder="搜索笔记..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={{
              width: '100%',
              padding: '10px 12px 10px 40px',
              border: '1px solid #ddd',
              borderRadius: '8px',
              fontSize: '0.95rem'
            }}
          />
        </div>

        <select
          value={selectedCategory}
          onChange={(e) => setSelectedCategory(e.target.value)}
          style={{
            padding: '10px 16px',
            border: '1px solid #ddd',
            borderRadius: '8px',
            fontSize: '0.95rem',
            minWidth: '150px'
          }}
        >
          {categories.map(cat => (
            <option key={cat} value={cat}>{cat}</option>
          ))}
        </select>
      </div>

      {/* 标签云 */}
      {allTags.length > 0 && (
        <div style={{ marginBottom: '24px' }}>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
            {allTags.map(tag => (
              <button
                key={tag}
                onClick={() => setSearchQuery(tag)}
                style={{
                  padding: '4px 12px',
                  background: searchQuery === tag ? '#667eea' : '#f0f4ff',
                  color: searchQuery === tag ? 'white' : '#667eea',
                  border: 'none',
                  borderRadius: '16px',
                  fontSize: '0.85rem',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px'
                }}
              >
                <Tag size={12} />
                {tag}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* 笔记列表 */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
        gap: '20px'
      }}>
        {filteredNotes.map(note => (
          <div
            key={note.id}
            className="card"
            style={{
              display: 'flex',
              flexDirection: 'column',
              cursor: 'pointer',
              transition: 'transform 0.2s, box-shadow 0.2s'
            }}
            onClick={() => openEdit(note)}
          >
            <div style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'flex-start',
              marginBottom: '12px'
            }}>
              <div style={{
                width: '40px',
                height: '40px',
                borderRadius: '8px',
                background: '#f0f4ff',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#667eea'
              }}>
                <FileText size={20} />
              </div>
              <div style={{ display: 'flex', gap: '8px' }}>
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    openEdit(note)
                  }}
                  style={{
                    padding: '6px',
                    background: 'none',
                    border: 'none',
                    cursor: 'pointer',
                    color: '#667eea'
                  }}
                >
                  <Edit2 size={16} />
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    handleDelete(note.id)
                  }}
                  style={{
                    padding: '6px',
                    background: 'none',
                    border: 'none',
                    cursor: 'pointer',
                    color: '#ef4444'
                  }}
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>

            <h3 style={{
              margin: '0 0 8px 0',
              fontSize: '1.1rem',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical'
            }}>
              {note.title}
            </h3>

            <p style={{
              margin: '0 0 12px 0',
              color: '#666',
              fontSize: '0.9rem',
              lineHeight: 1.5,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              display: '-webkit-box',
              WebkitLineClamp: 3,
              WebkitBoxOrient: 'vertical',
              flex: 1
            }}>
              {note.content}
            </p>

            <div style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginTop: 'auto',
              paddingTop: '12px',
              borderTop: '1px solid #e9ecef'
            }}>
              <span style={{
                fontSize: '0.8rem',
                color: '#666',
                padding: '2px 8px',
                background: '#f0f0f0',
                borderRadius: '4px'
              }}>
                {note.category}
              </span>
              <span style={{ fontSize: '0.8rem', color: '#999' }}>
                {new Date(note.updatedAt).toLocaleDateString('zh-CN')}
              </span>
            </div>

            {note.tags.length > 0 && (
              <div style={{
                display: 'flex',
                gap: '6px',
                marginTop: '8px',
                flexWrap: 'wrap'
              }}>
                {note.tags.slice(0, 3).map((tag, i) => (
                  <span
                    key={i}
                    style={{
                      fontSize: '0.75rem',
                      color: '#667eea',
                      background: '#f0f4ff',
                      padding: '2px 8px',
                      borderRadius: '4px'
                    }}
                  >
                    {tag}
                  </span>
                ))}
                {note.tags.length > 3 && (
                  <span style={{
                    fontSize: '0.75rem',
                    color: '#999'
                  }}>
                    +{note.tags.length - 3}
                  </span>
                )}
              </div>
            )}
          </div>
        ))}
      </div>

      {filteredNotes.length === 0 && (
        <div style={{
          textAlign: 'center',
          padding: '60px 20px',
          color: '#999'
        }}>
          <FileText size={48} style={{ marginBottom: '16px', opacity: 0.5 }} />
          <p>没有找到匹配的笔记</p>
        </div>
      )}

      {/* 编辑弹窗 */}
      {showModal && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000
          }}
          onClick={() => setShowModal(false)}
        >
          <div
            style={{
              background: 'white',
              borderRadius: '12px',
              padding: '24px',
              width: '90%',
              maxWidth: '700px',
              maxHeight: '80vh',
              overflow: 'auto'
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 style={{ marginBottom: '20px' }}>
              {editingNote ? '编辑笔记' : '新建笔记'}
            </h3>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  标题 *
                </label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  placeholder="输入笔记标题"
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px',
                    fontSize: '1rem'
                  }}
                />
              </div>

              <div style={{ display: 'flex', gap: '12px' }}>
                <div style={{ flex: 1 }}>
                  <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                    分类
                  </label>
                  <select
                    value={formData.category}
                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                    style={{
                      width: '100%',
                      padding: '10px',
                      border: '1px solid #ddd',
                      borderRadius: '6px'
                    }}
                  >
                    {categories.filter(c => c !== '全部').map(cat => (
                      <option key={cat} value={cat}>{cat}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  标签
                </label>
                <div style={{ display: 'flex', gap: '8px', marginBottom: '8px' }}>
                  <input
                    type="text"
                    value={newTag}
                    onChange={(e) => setNewTag(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addTag())}
                    placeholder="添加标签"
                    style={{
                      flex: 1,
                      padding: '8px',
                      border: '1px solid #ddd',
                      borderRadius: '6px'
                    }}
                  />
                  <button
                    onClick={addTag}
                    style={{
                      padding: '8px 16px',
                      background: '#667eea',
                      color: 'white',
                      border: 'none',
                      borderRadius: '6px',
                      cursor: 'pointer'
                    }}
                  >
                    <Plus size={16} />
                  </button>
                </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
                  {formData.tags?.map(tag => (
                    <span
                      key={tag}
                      style={{
                        padding: '4px 12px',
                        background: '#f0f4ff',
                        color: '#667eea',
                        borderRadius: '16px',
                        fontSize: '0.85rem',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '6px'
                      }}
                    >
                      {tag}
                      <button
                        onClick={() => removeTag(tag)}
                        style={{
                          background: 'none',
                          border: 'none',
                          color: '#667eea',
                          cursor: 'pointer',
                          padding: 0,
                          display: 'flex'
                        }}
                      >
                        <X size={12} />
                      </button>
                    </span>
                  ))}
                </div>
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                  内容
                </label>
                <textarea
                  value={formData.content}
                  onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                  placeholder="输入笔记内容..."
                  rows={10}
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ddd',
                    borderRadius: '6px',
                    resize: 'vertical',
                    fontSize: '0.95rem',
                    lineHeight: 1.6
                  }}
                />
              </div>
            </div>

            <div style={{
              display: 'flex',
              gap: '12px',
              justifyContent: 'flex-end',
              marginTop: '24px'
            }}>
              <button
                onClick={() => setShowModal(false)}
                style={{
                  padding: '10px 20px',
                  background: '#f0f0f0',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px'
                }}
              >
                <X size={16} />
                取消
              </button>
              <button
                onClick={handleSave}
                disabled={!formData.title}
                style={{
                  padding: '10px 20px',
                  background: !formData.title ? '#ccc' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: !formData.title ? 'not-allowed' : 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px'
                }}
              >
                <Save size={16} />
                保存
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
