import { useState, useEffect } from 'react'
import './LogViewer.css'

interface LogEntry {
  id: number
  level: string
  source: string
  message: string
  timestamp: string
  metadata: Record<string, any>
}

interface AuditLogEntry {
  id: number
  admin_id: number
  admin_username: string
  action: string
  target_type: string
  target_id: string
  details: Record<string, any>
  ip_address: string
  created_at: string
}

export function LogViewer() {
  const [activeTab, setActiveTab] = useState<'system' | 'audit'>('system')
  const [logs, setLogs] = useState<LogEntry[]>([])
  const [auditLogs, setAuditLogs] = useState<AuditLogEntry[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  
  // 筛选条件
  const [filters, setFilters] = useState({
    level: '',
    source: '',
    startTime: '',
    endTime: ''
  })

  const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8086'
  const token = localStorage.getItem('kanban_token')

  useEffect(() => {
    if (activeTab === 'system') {
      fetchSystemLogs()
    } else {
      fetchAuditLogs()
    }
  }, [activeTab, page])

  const fetchSystemLogs = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        per_page: '50',
        ...(filters.level && { level: filters.level }),
        ...(filters.source && { source: filters.source }),
        ...(filters.startTime && { start_time: filters.startTime }),
        ...(filters.endTime && { end_time: filters.endTime })
      })

      const response = await fetch(`${API_URL}/api/admin/logs?${params}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()

      if (data.success) {
        setLogs(data.data.logs)
        setTotalPages(data.data.total_pages)
      } else {
        setError(data.error || '获取日志失败')
      }
    } catch (err) {
      setError('网络错误')
    } finally {
      setLoading(false)
    }
  }

  const fetchAuditLogs = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        per_page: '50'
      })

      const response = await fetch(`${API_URL}/api/admin/audit-logs?${params}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()

      if (data.success) {
        setAuditLogs(data.data.logs)
        setTotalPages(data.data.total_pages)
      } else {
        setError(data.error || '获取审计日志失败')
      }
    } catch (err) {
      setError('网络错误')
    } finally {
      setLoading(false)
    }
  }

  const getLevelColor = (level: string) => {
    switch (level.toLowerCase()) {
      case 'error': return '#ef4444'
      case 'warning': return '#f59e0b'
      case 'info': return '#3b82f6'
      case 'debug': return '#6b7280'
      default: return '#9ca3af'
    }
  }

  const getActionText = (action: string) => {
    const actions: Record<string, string> = {
      'update_user_status': '更新用户状态',
      'update_user_role': '更新用户角色',
      'delete_user': '删除用户',
      'update_config': '更新配置',
      'update_email_template': '更新邮件模板',
      'login': '登录',
      'logout': '登出'
    }
    return actions[action] || action
  }

  const handleExport = () => {
    const data = activeTab === 'system' ? logs : auditLogs
    const csv = convertToCSV(data)
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = `${activeTab}_logs_${new Date().toISOString().split('T')[0]}.csv`
    link.click()
  }

  const convertToCSV = (data: any[]) => {
    if (data.length === 0) return ''
    
    const headers = Object.keys(data[0])
    const rows = data.map(row => 
      headers.map(header => {
        const value = row[header]
        if (typeof value === 'object') {
          return `"${JSON.stringify(value).replace(/"/g, '""')}"`
        }
        return `"${String(value).replace(/"/g, '""')}"`
      }).join(',')
    )
    
    return [headers.join(','), ...rows].join('\n')
  }

  return (
    <div className="log-viewer">
      <div className="log-header">
        <h1>日志查看</h1>
        <button className="btn-export" onClick={handleExport}>
          📥 导出日志
        </button>
      </div>

      {/* 标签页 */}
      <div className="tabs">
        <button 
          className={`tab ${activeTab === 'system' ? 'active' : ''}`}
          onClick={() => { setActiveTab('system'); setPage(1); }}
        >
          系统日志
        </button>
        <button 
          className={`tab ${activeTab === 'audit' ? 'active' : ''}`}
          onClick={() => { setActiveTab('audit'); setPage(1); }}
        >
          审计日志
        </button>
      </div>

      {/* 筛选器 */}
      {activeTab === 'system' && (
        <div className="filter-bar">
          <select
            value={filters.level}
            onChange={(e) => setFilters({ ...filters, level: e.target.value })}
            className="filter-select"
          >
            <option value="">所有级别</option>
            <option value="error">错误</option>
            <option value="warning">警告</option>
            <option value="info">信息</option>
            <option value="debug">调试</option>
          </select>
          <input
            type="text"
            placeholder="来源..."
            value={filters.source}
            onChange={(e) => setFilters({ ...filters, source: e.target.value })}
            className="filter-input"
          />
          <input
            type="datetime-local"
            value={filters.startTime}
            onChange={(e) => setFilters({ ...filters, startTime: e.target.value })}
            className="filter-input"
          />
          <input
            type="datetime-local"
            value={filters.endTime}
            onChange={(e) => setFilters({ ...filters, endTime: e.target.value })}
            className="filter-input"
          />
          <button onClick={() => { setPage(1); fetchSystemLogs(); }} className="btn-primary">
            筛选
          </button>
        </div>
      )}

      {/* 日志表格 */}
      {loading ? (
        <div className="admin-loading">加载中...</div>
      ) : error ? (
        <div className="admin-error">{error}</div>
      ) : (
        <>
          {activeTab === 'system' ? (
            <div className="logs-table-container">
              <table className="admin-table logs-table">
                <thead>
                  <tr>
                    <th>时间</th>
                    <th>级别</th>
                    <th>来源</th>
                    <th>消息</th>
                    <th>元数据</th>
                  </tr>
                </thead>
                <tbody>
                  {logs.map(log => (
                    <tr key={log.id} className={`log-level-${log.level.toLowerCase()}`}>
                      <td className="log-time">
                        {new Date(log.timestamp).toLocaleString()}
                      </td>
                      <td>
                        <span 
                          className="level-badge"
                          style={{ backgroundColor: getLevelColor(log.level) }}
                        >
                          {log.level}
                        </span>
                      </td>
                      <td className="log-source">{log.source}</td>
                      <td className="log-message">{log.message}</td>
                      <td className="log-metadata">
                        {Object.keys(log.metadata).length > 0 && (
                          <details>
                            <summary>查看</summary>
                            <pre>{JSON.stringify(log.metadata, null, 2)}</pre>
                          </details>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="logs-table-container">
              <table className="admin-table logs-table">
                <thead>
                  <tr>
                    <th>时间</th>
                    <th>管理员</th>
                    <th>操作</th>
                    <th>目标类型</th>
                    <th>目标ID</th>
                    <th>详情</th>
                    <th>IP地址</th>
                  </tr>
                </thead>
                <tbody>
                  {auditLogs.map(log => (
                    <tr key={log.id}>
                      <td className="log-time">
                        {new Date(log.created_at).toLocaleString()}
                      </td>
                      <td>{log.admin_username || `ID:${log.admin_id}`}</td>
                      <td>
                        <span className="action-badge">
                          {getActionText(log.action)}
                        </span>
                      </td>
                      <td>{log.target_type}</td>
                      <td>{log.target_id || '-'}</td>
                      <td className="log-details">
                        {Object.keys(log.details).length > 0 && (
                          <details>
                            <summary>查看</summary>
                            <pre>{JSON.stringify(log.details, null, 2)}</pre>
                          </details>
                        )}
                      </td>
                      <td className="log-ip">{log.ip_address || '-'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* 分页 */}
          <div className="pagination">
            <button 
              disabled={page === 1}
              onClick={() => setPage(page - 1)}
              className="btn-page"
            >
              上一页
            </button>
            <span className="page-info">
              第 {page} 页 / 共 {totalPages} 页
            </span>
            <button 
              disabled={page === totalPages}
              onClick={() => setPage(page + 1)}
              className="btn-page"
            >
              下一页
            </button>
          </div>
        </>
      )}
    </div>
  )
}
